prompt --application/shared_components/automations/process_advance_fee_students
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(72491337630695382194)
,p_name=>'Process Advance Fee Students'
,p_static_id=>'process-advance-fee-students'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=12;BYMINUTE=0'
,p_polling_status=>'ACTIVE'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_type=>'SQL'
,p_query_source=>'SELECT SYSDATE AS run_date FROM dual;'
,p_include_rowid_column=>false
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(72491338006028382196)
,p_automation_id=>wwv_flow_imp.id(72491337630695382194)
,p_name=>'New Action'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_today       DATE := TRUNC(SYSDATE);',
'    v_day         NUMBER := TO_NUMBER(TO_CHAR(SYSDATE, ''DD''));',
'    v_last_day    NUMBER := TO_NUMBER(TO_CHAR(LAST_DAY(SYSDATE), ''DD''));',
'    v_run_exists  NUMBER;',
'BEGIN',
'    -- Ensure log table exists',
'    BEGIN',
'        EXECUTE IMMEDIATE ''CREATE TABLE job_run_log (run_date DATE PRIMARY KEY)'';',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            IF SQLCODE != -955 THEN -- Table already exists',
'                RAISE;',
'            END IF;',
'    END;',
'',
'    -- Check agar iss month me pehle run hua hai ya nahi',
'    SELECT COUNT(*) INTO v_run_exists',
'    FROM job_run_log',
'    WHERE TO_CHAR(run_date, ''YYYYMM'') = TO_CHAR(SYSDATE, ''YYYYMM'');',
'',
'    IF v_run_exists = 0 THEN',
'        IF v_day = 25 OR (v_day > 25 AND v_day < v_last_day) THEN',
'            -- Call your procedure',
'            PROCESSADVANCEFEESTUDENTS;',
'',
'            -- Log this run',
'            INSERT INTO job_run_log (run_date) VALUES (v_today);',
'            COMMIT;',
'        END IF;',
'    END IF;',
'END;',
''))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
