 p_id=>wwv_flow_imp.id(15599047212084988116)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Role To User'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P7_ROLE_ID IS NOT NULL THEN  ',
'  DELETE FROM ASSIGN_ROLE_USER',
'        WHERE APP_USER=:P7_APP_USER',
'          AND (ROLE_ID NOT IN (SELECT REGEXP_SUBSTR(:P7_ROLE_ID, ''[^:]+'', 1, LEVEL) AS V_CNT',
'                                FROM DUAL',
'                                CONNECT BY REGEXP_SUBSTR(:P7_ROLE_ID, ''[^:]+'', 1, LEVEL) IS NOT NULL)',
'          )                  ',
'   ;                                                            ',
'    INSERT INTO ASSIGN_ROLE_USER(APP_USER,ROLE_ID)',
'         SELECT :P7_APP_USER,V_CNT',
'         FROM ASSIGN_ROLE_USER U,(SELECT REGEXP_SUBSTR(:P7_ROLE_ID, ''[^:]+'', 1, LEVEL) AS V_CNT',
'                                   FROM DUAL',
'                                   CONNECT BY REGEXP_SUBSTR(:P7_ROLE_ID, ''[^:]+'', 1, LEVEL) IS NOT NULL)R',
'         WHERE U.APP_USER(+)=:P7_APP_USER',
'         AND   U.ROLE_ID(+)  =R.V_CNT',
'         AND   U.ROLE_ID IS NULL',
'         ;',
'ELSIF :P7_ROLE_ID IS NULL THEN   ',
'      DELETE FROM ASSIGN_ROLE_USER',
'        WHERE APP_USER=:P7_APP_USER',
'        ;    ',
'END IF;         '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Role Assign'
,p_internal_uid=>15599047212084988116
);
