wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17219560336675594016)
,p_plug_name=>'Student Admission Form'
,p_region_name=>'student_admission_form'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_html CLOB := ''<html><head>',
'                    </head><body>',
'                    <div class="container" id="Student_info">'';',
'    v_count NUMBER;',
'    v_total_hours number;',
'BEGIN',
'              v_html := v_html || ''<h3 id="adrpt">Admission Form</h3>''   ;              ',
'    -- Student Information Section',
'    SELECT COUNT(*) INTO v_count FROM STUDENTS WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID;',
'    SELECT NVL(SUM( ROUND((TO_DATE(C.END_TIME, ''HH24:MI'') - TO_DATE(C.START_TIME, ''HH24:MI'')) * 24, 2)),0) into v_total_hours',
'      FROM STUDENT_CLASSES_SCHEDULE S,CLASS_SCHEDULE C',
'     WHERE S.CLASS_SHEDULE_ID=C.SCHEDULE_ID ',
'       AND S.SITE_ID         =C.SITE_ID',
'       AND S.STUDENT_ID      =:P16_STUDENT_ID',
'       AND S.SITE_ID         =:APP_SITE_ID',
'       ;',
'    IF v_count > 0 THEN',
'       FOR rec IN (',
'            SELECT STUDENT_ID,STUDENT_NAME||'' ''||LAST_NAME STUDENT_NAME, DATE_OF_BIRTH, ',
'                   DECODE(GENDER,''M'',''Male'',''F'',''Female'')GENDER,',
'                   LEARNING_NEED,SCHOOL_NAME, MEDICAL_CONDITION,SESSIONS',
'            FROM STUDENTS ',
'            WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<h2>Student Information</h2>',
'            <table>',
'            <tr><th>Admission No:</th><td>'' || APEX_ESCAPE.HTML(rec.STUDENT_ID) || ''</td></tr>',
'            <tr><th>Student Name:</th><td>'' || APEX_ESCAPE.HTML(rec.STUDENT_NAME) || ''</td></tr>',
'            <tr><th>Date of Birth:</th><td>'' || APEX_ESCAPE.HTML(TO_CHAR(rec.DATE_OF_BIRTH, ''DD-Mon-YYYY'')) || ''</td></tr>',
'            <tr><th>Gender:</th><td>'' || APEX_ESCAPE.HTML(rec.GENDER) || ''</td></tr>',
'            <tr><th>Medical Condition:</th><td>'' || APEX_ESCAPE.HTML(NVL(rec.MEDICAL_CONDITION, ''N/A'')) || ''</td></tr>',
'            <tr><th>Learning Needs:</th><td>'' || APEX_ESCAPE.HTML(rec.LEARNING_NEED) || ''</td></tr>',
'            <tr><th>School Name:</th><td>'' || APEX_ESCAPE.HTML(rec.SCHOOL_NAME) || ''</td></tr>',
'            <tr><th>Session:</th><td>'' || APEX_ESCAPE.HTML(rec.SESSIONS) || ''</td></tr>',
'             <tr><th>Total Hours:</th><td>'' || v_total_hours|| ''</td></tr>',
'            </table>'';',
'        END LOOP;',
'    /*ELSE',
'        v_html := v_html || ''<p class="error">No student data found.</p>'';*/',
'    END IF;',
'',
'    -- Parent Information Section',
'    SELECT COUNT(*) INTO v_count FROM STUDENT_PARENTS WHERE STUDENT_ID=:P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID;',
'    IF v_count > 0 THEN',
'        FOR rec IN (',
'            SELECT PARENT_NAME, RELATIONSHIP, CONTACT_NUMBER, EMAIL, OCCUPATION, ADDRESS, EME_CONT_NUMBER',
'            FROM STUDENT_PARENTS',
'            WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<h2>Parent / Guardian</h2>',
'            <table>',
'            <tr><th>Parent Name:</th><td>'' || APEX_ESCAPE.HTML(rec.PARENT_NAME) || ''</td></tr>',
'            <tr><th>Relationship:</th><td>'' || APEX_ESCAPE.HTML(rec.RELATIONSHIP) || ''</td></tr>',
'            <tr><th>Contact:</th><td>'' || APEX_ESCAPE.HTML(rec.CONTACT_NUMBER) || ''</td></tr>',
'            <tr><th>Email:</th><td>'' || APEX_ESCAPE.HTML(rec.EMAIL) || ''</td></tr>',
'            <tr><th>Occupation:</th><td>'' || APEX_ESCAPE.HTML(rec.OCCUPATION) || ''</td></tr>',
'            <tr><th>Address:</th><td>'' || APEX_ESCAPE.HTML(rec.ADDRESS) || ''</td></tr>',
'            <tr><th>Emergancy Contact:</th><td>'' || APEX_ESCAPE.HTML(rec.EME_CONT_NUMBER) || ''</td></tr>',
'            </table>'';',
'        END LOOP;',
'    END IF;',
'',
'  /*  -- Emergency Contact Section (Modified to table format)',
'    SELECT COUNT(*) INTO v_count FROM STUDENT_EMERGENCY_CONTACTS WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID;',
'    IF v_count > 0 THEN',
'        v_html := v_html || ''<h2>Emergency Contact</h2>',
'            <table>',
'            <tr><th>Contact Name</th><th>Relationship</th><th>Contact Number</th></tr>'';',
'        FOR rec IN (',
'            SELECT CONTACT_NAME, RELATIONSHIP, CONTACT_NUMBER',
'            FROM STUDENT_EMERGENCY_CONTACTS',
'            WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<tr><td>'' || APEX_ESCAPE.HTML(rec.CONTACT_NAME) || ''</td>',
'                                  <td>'' || APEX_ESCAPE.HTML(rec.RELATIONSHIP) || ''</td>',
'                                  <td>'' || APEX_ESCAPE.HTML(rec.CONTACT_NUMBER) || ''</td></tr>'';',
'        END LOOP;',
'        v_html := v_html || ''</table>'';',
'    END IF;',
'    */',
'',
'    -- Reference Section (Modified to table format)',
'    SELECT COUNT(*) INTO v_count FROM STUDENT_REFERENCES WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID;',
'    IF v_count > 0 THEN',
'        v_html := v_html || ''<h2>Referral</h2>',
'            <table>',
'            <tr><th>Referred By</th><th>Referred Student ID</th></tr>'';',
'        FOR rec IN (',
'            SELECT REF_NAME,REFRENCE_STUDENT_ID',
'            FROM STUDENT_REFERENCES',
'            WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<tr><td>'' || APEX_ESCAPE.HTML(rec.REF_NAME) || ''</td><td>'' || APEX_ESCAPE.HTML(rec.REFRENCE_STUDENT_ID) || ''</td></tr>'';',
'        END LOOP;',
'        v_html := v_html || ''</table>'';',
'    END IF;',
' -- Classes Shedule Details Section (Modified to table format)',
'    SELECT COUNT(*) INTO v_count FROM CLASS_SCHEDULE C,STUDENT_CLASSES_SCHEDULE S',
'        WHERE SCHEDULE_ID = CLASS_SHEDULE_ID',
'        AND S.STUDENT_ID=:P16_STUDENT_ID AND S.SITE_ID = :APP_SITE_ID;',
'        ',
'    IF v_count > 0 THEN',
'          v_html := v_html || ''<h2>Lesson Plan</h2>',
'                             <table>',
'                             <tr><th>Subject</th><th>Book Name</th><th>WeekDays</th><th>Start Time</th><th>End Time</th></tr>'';',
'',
'        -- Loop through the records and add data rows',
'        FOR rec IN (',
'            SELECT SB.SUBJECT_NAME SUBJECT,BOOK_NAME,C.WEEKDAY, C.START_TIME, C.END_TIME',
'            FROM CLASS_SCHEDULE C, STUDENT_CLASSES_SCHEDULE S,BOOKS B,SUBJECTS SB',
'            WHERE S.CLASS_SHEDULE_ID = C.SCHEDULE_ID',
'              AND S.BOOK_ID=B.BOOK_ID',
'              AND S.SUBJECT_ID=SB.SUBJECT_ID',
'              AND S.STUDENT_ID = :P16_STUDENT_ID',
'              AND S.SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<tr><td>'' || rec.SUBJECT || ''</td>',
'                                <td>'' || rec.BOOK_NAME || ''</td>',
'                                 <td>'' || rec.WEEKDAY || ''</td>',
'                                 <td>'' || rec.START_TIME || ''</td>',
'                                 <td>'' || rec.END_TIME || ''</td></tr>'';',
'        END LOOP;',
'',
'        -- Close the table after the loop',
'        v_html := v_html || ''</table>'';',
'    END IF;',
'     -- Assessment Result and Books Allotment (Modified to table format)',
'    SELECT COUNT(*) INTO v_count ',
'      FROM STUDENT_ADMISSION_TEST SAT',
'     WHERE SAT.STUDENT_ID=:P16_STUDENT_ID ',
'       AND SAT.SITE_ID = :APP_SITE_ID;',
'        ',
'    IF v_count > 0 THEN',
'         -- Add the header and table structure once',
'        v_html := v_html || ''<h2>Assessment Result</h2>',
'                             <table>',
'                             <tr><th>Assessment Date</th><th>Assessment Subject</th><th>Score</th></tr>'';',
'',
'        -- Loop through the records and add data rows',
'        FOR rec IN (',
'            SELECT DISTINCT TO_CHAR(SAT.TEST_DATE,''DD-MON-YYYY'')TEST_DATE,S.SUBJECT_NAME SUBJECT, SAT.SCORE || ''%'' AS SCORE',
'            FROM STUDENT_ADMISSION_TEST SAT,SUBJECTS S',
'            WHERE SAT.SUBJECT_ID=S.SUBJECT_ID',
'              AND SAT.STUDENT_ID = :P16_STUDENT_ID ',
'              AND SAT.SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<tr><td>'' || rec.TEST_DATE || ''</td>',
'                                 <td>'' || rec.SUBJECT || ''</td>',
'                                 <td>'' || rec.SCORE || ''</td></tr>'';',
'        END LOOP;',
'        v_html := v_html || ''</table>'';',
'    END IF;',
'-------BOOKS ALLOTMENT--------------------------',
'    SELECT COUNT(*) INTO v_count ',
'      FROM STUDENT_BOOKS_ALLOTMENT SBA',
'     WHERE SBA.STUDENT_ID=:P16_STUDENT_ID',
'       AND SBA.SITE_ID   =:APP_SITE_ID',
'       ; ',
'    IF v_count > 0 THEN',
'         -- Add the header and table structure once--------',
'        v_html := v_html || ''<h2>Books Recommendation</h2>',
'                             <table>',
'                             <tr><th>Books Alloted</th><th>Subject</th></tr>'';',
'',
'        -- Loop through the records and add data rows',
'        FOR rec IN (',
'            SELECT B.BOOK_NAME,S.SUBJECT_NAME SUBJECT',
'              FROM STUDENT_BOOKS_ALLOTMENT SBA,BOOKS B,SUBJECTS S',
'             WHERE SBA.BOOK_ID=B.BOOK_ID',
'               AND B.SUBJECT_ID=S.SUBJECT_ID',
'               AND SBA.STUDENT_ID=:P16_STUDENT_ID',
'               AND SBA.SITE_ID   =:APP_SITE_ID ',
'        ) LOOP',
'            v_html := v_html || ''<tr><td>'' || rec.BOOK_NAME || ''</td>',
'                                 <td>'' || rec.SUBJECT || ''</td></tr>'';',
'        END LOOP;',
'        v_html := v_html || ''</table>'';',
'    END IF;',
'    -- Fee Details Section-------------------',
'    SELECT COUNT(*) INTO v_count FROM STUDENT_FEES WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID;',
'    IF v_count > 0 THEN',
'        FOR rec IN (',
unistr('            SELECT ''\00A3''||'' ''||NVL(REGISTRATION_FEE,0) REGISTRATION_FEE,''\00A3''||'' ''||NVL(BOOK_FEE,0) BOOK_FEE,''\00A3''||'' ''||NVL(EXAM_FEE,0) EXAM_FEE'),
unistr('                   ,''\00A3''||'' ''||NVL(HOURLY_FEE,0) HOURLY_FEE,''\00A3''||'' ''||NVL(PAST_PAPER_FEE,0) PAST_PAPER_FEE,'),
unistr('                   ''\00A3''||'' ''||NVL(TOTAL_FEE,0) TOTAL_FEE,'),
'                   DUE_DATE, PAYMENT_NAME PAYMENT_METHOD',
'            FROM STUDENT_FEES S,PAYMENT_TYPE P',
'            WHERE S.PAY_ID=P.PAY_ID',
'              AND  STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || ''<h2>Fee Details</h2>',
'            <table id="fee_table">',
'            <tr><th>Registration Fee</th><th>Books Fee</th><th>Exams Fee</th><th>Hourly Fee</th><th>Past Papers Fee</th><th>Monthly Fee</th><th>Due Date</th><th>Payment Method</th></tr>',
'            <tr><td>'' || rec.REGISTRATION_FEE || ''</td>',
'                <td>'' || rec.BOOK_FEE || ''</td>',
'                <td>'' || rec.EXAM_FEE || ''</td>',
'                <td>'' || rec.HOURLY_FEE || ''</td>',
'                <td>'' || rec.PAST_PAPER_FEE || ''</td>',
'                <td><b>'' || rec.TOTAL_FEE || ''</b></td>',
'                <td>'' || rec.DUE_DATE || ''</td>',
'                <td>'' || rec.PAYMENT_METHOD || ''</td></tr>',
'            </table>'';',
'        END LOOP;',
'    END IF;',
'       -- Meetings-------------------------',
'    SELECT COUNT(*) INTO v_count FROM STUDENT_MEETING_COMMENTS WHERE STUDENT_ID = :P16_STUDENT_ID AND SITE_ID = :APP_SITE_ID;',
'        IF v_count > 0 THEN',
'         -- Add the header and table structure once--------',
'        v_html := v_html || ''<h2>HOC / Meetings</h2>',
'                             <table>',
'                             <tr><th>Meeting#</th><th>Meetings</th><th>Meeting Date</th></tr>'';',
'        -- Loop through the records and add data rows',
'        FOR rec IN (',
'            SELECT ''Meeting''||'' ''||COMMENTS_NO COMMENTS_NO,COMMENTS, TO_CHAR(FEED_DATE,''DD-MON-YYYY'')FEED_DATE',
'                from STUDENT_MEETING_COMMENTS',
'               where STUDENT_ID = :P16_STUDENT_ID ',
'                 AND SITE_ID    = :APP_SITE_ID',
'        ) LOOP',
'            v_html := v_html || '' <tr><td>'' || rec.COMMENTS_NO || ''</td>',
'                                <td>'' || rec.COMMENTS || ''</td>',
'                                <td>'' || rec.FEED_DATE || ''</td>',
'                                </tr>'';',
'        END LOOP;',
'        v_html := v_html || ''</table>'';',
'    END IF;',
'        v_html := v_html || ''<h2>Payment Terms:</h2>',
'        <ul class="ui-list">',
'        <li>The monthly fee must be paid on the 1st of each month.</br>',
'            Failure to make a paymnet will result is pausing your child''''s lessons until the fee has been cleared.</br>',
'            We will pause your child''''s'''' lesson for 2 weeks. if the payment still hasn''''t been made, their lesson will be suspended.',
'        </li>',
'        <li><u>The admission fee is a one-off paymnet</u> and is non-refundable.</li>',
'          <li style="display: inline-block;">Photo consent: Permission to use pirctures on our website and social media accounts.',
'           I have understood and agreef to all the T&C''''s on this form.</br>',
'        <li>The book fee is a one-off payment for the academic year and is <u>non-refundable.</u></br>',
unistr('            if students lose their books there will be a <u>charge of \00A39.95</u> for a replacment.'),
'        </li>',
'        </li>',
'        <li><b>Parent Signature:</b> <hr style="width: 300px; margin-top: 70px; border: none; border-bottom: 1px solid black; display: inline-block; vertical-align: bottom;"></li>',
'',
'    </ul>'';',
'    -- Ensure we have output; otherwise, return an error message',
'    IF v_html IS NULL OR LENGTH(v_html) = 0 THEN',
'        v_html := v_html || ''<p class="error">No records found.</p>'';',
'    END IF;',
'',
'    -- Close HTML div',
'   -- v_html := v_html || ''</div><div class="report-footer">Generated by Student Management System</div></body></html>'';',
'',
'    -- Output the formatted HTML',
'    HTP.P(v_html);',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(''<p class="error">Error: '' || APEX_ESCAPE.HTML(SQLERRM) || ''</p>'');',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
