,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "EMP_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P17_EMP_ID'', p_values => "EMP_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P17_EMP_ID,''0'') = "EMP_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("EMP_ID", 1, 50)||( case when length("EMP_ID") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("EMP_NAME", 1, 50)||( case when length("EMP_NAME") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "EMPLOYEES" x',
'where (:P17_SEARCH is null',
'        or upper(x."EMP_ID") like ''%''||upper(:P17_SEARCH)||''%''',
'        or upper(x."EMP_NAME") like ''%''||upper(:P17_SEARCH)||''%''',
'    )',
'    AND SITE_ID=:APP_SITE_ID',
'order by "EMP_ID"'))
