,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select SCHEDULE_ID,',
'       WEEKDAY,',
'       START_TIME,',
'       END_TIME,',
'       SITE_NAME,',
'       DECODE(CS.STATUS,''A'',''Active'',''I'',''In-Active'')STATUS,',
'       CS.FEED_BY,',
'       TO_CHAR(CS.FEED_DATE,''DD-MON-YYYY'')FEED_DATE',
'  from CLASS_SCHEDULE CS,SITES S',
'  WHERE CS.SITE_ID=S.SITE_ID',
'    AND CS.WEEKDAY =NVL(:P25_WEEKDAY,CS.WEEKDAY)',
'    AND CS.START_TIME=NVL(:P25_START_TIME,CS.START_TIME)',
'    AND CS.END_TIME=NVL(:P25_END_TIME,CS.END_TIME)',
'    AND CS.SITE_ID=:APP_SITE_ID',
'    order by WEEKDAY ',
'    '))
,p_ajax_enabled=>'Y'
