'   V_PERM NUMBER;',
'BEGIN',
'   SELECT COUNT(*)',
'   INTO V_PERM',
'   FROM ROLE_PERMISSIONS RP',
'   WHERE RP.ROLE_ID IN (',
'                       SELECT ROLE_ID',
'                         FROM ASSIGN_ROLE_USER',
'                        WHERE APP_USER = :APP_USER',
'                        )',
'   AND RP.PERMISSION_ID IN (21, 60);',
'',
'   IF V_PERM > 0 THEN',
'      RETURN TRUE;',
'   ELSE',
'      RETURN FALSE;',
'   END IF;',
'END;'))
