 p_id=>wwv_flow_imp.id(20640475742652856135)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'transfer shedule'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P25_BRANCH IS NOT NULL THEN',
'    INSERT INTO CLASS_SCHEDULE(WEEKDAY,START_TIME,END_TIME,STATUS,FEED_BY,FEED_DATE,SITE_ID)',
'      SELECT WEEKDAY,START_TIME,END_TIME,STATUS,:APP_USER,TRUNC(SYSDATE),:P25_BRANCH',
'        FROM CLASS_SCHEDULE C ',
'       WHERE C.STATUS=''A''',
'         AND C.SITE_ID   =:APP_SITE_ID',
'         AND C.WEEKDAY   =NVL(:P25_WEEKDAY,C.WEEKDAY)',
'         AND C.START_TIME=NVL(:P25_START_TIME,C.START_TIME)',
'         AND C.END_TIME=NVL(:P25_END_TIME,C.END_TIME)',
'         AND (WEEKDAY,START_TIME,END_TIME) NOT IN (SELECT WEEKDAY,START_TIME,END_TIME',
'                                                                 FROM CLASS_SCHEDULE S',
'                                                                WHERE SITE_ID=:P25_BRANCH',
'                                                                );',
'            END IF;                                                                                '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(20640475617533856134)
,p_process_when=>'P25_BRANCH'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_process_success_message=>'Data transfer successfully.'
,p_internal_uid=>20640475742652856135
);
