 p_id=>wwv_flow_imp.id(16038238616897059132)
,p_validation_name=>'Unique Record'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
' BEGIN',
'    SELECT COUNT(*) INTO V_CNT',
'      FROM CLASS_SCHEDULE CS   ',
'     WHERE CS.SITE_ID   =:P26_SITE_ID',
'       AND CS.WEEKDAY   =:P26_WEEKDAY',
'       AND CS.START_TIME=:P26_START_TIME',
'       AND CS.END_TIME  =:P26_END_TIME',
'       --AND CS.TUTION_TIME=:P26_TUTION_TIME',
'       ;  ',
'     IF V_CNT > 0 THEN',
'        RETURN FALSE;',
'     ELSE',
'        RETURN TRUE;',
'     END IF;',
' END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Data Already Exists.'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
