'    AND B.CLASS_ID=C.CLASS_ID',
'    AND B.CLASS_ID=NVL(:P27_SCHOOL_YEAR,B.CLASS_ID)',
'    AND B.SUBJECT_ID=NVL(:P27_SUBEJCT,B.SUBJECT_ID)',
