,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN',
'  SELECT COUNT(*) INTO V_CNT',
'    FROM BOOKS B    ',
'   WHERE B.CLASS_ID  =:P28_CLASS_ID',
'     AND B.SUBJECT_ID=:P28_SUBJECT',
'     AND B.BOOK_NAME=:P28_BOOK_NAME',
'     ; ',
'    IF V_CNT > 0 THEN',
'        RETURN FALSE;',
'    ELSE',
'       RETURN TRUE;',
'    END IF;',
'END;'))
