,p_plug_name=>'Student Lesson Plan'
,p_title=>'Student Lesson Plan'
,p_region_name=>'lesson_plan_grid'
,p_parent_plug_id=>wwv_flow_imp.id(31678745606889883525)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody:margin-top-none:margin-bottom-none'
