,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>70
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select STUDENT_SCHEDULE_ID,',
'       S.STUDENT_ID,',
'       CS.CLASS_NAME,',
'       SB.SUBJECT_NAME,',
'       B.BOOK_NAME,',
'       C.WEEKDAY,',
'       C.START_TIME,',
'       C.END_TIME,',
'       CLASS_SHEDULE_ID,',
'       S.STATUS,',
'       S.FEED_BY,',
'       S.FEED_DATE,',
'       S.SITE_ID',
'  from STUDENT_CLASSES_SCHEDULE S,CLASS_SCHEDULE C,SUBJECTS SB,BOOKS B,CLASSES CS',
' where S.CLASS_SHEDULE_ID=C.SCHEDULE_ID',
'   AND S.SITE_ID   =C.SITE_ID',
'   AND S.SUBJECT_ID=SB.SUBJECT_ID',
'   AND S.BOOK_ID   =B.BOOK_ID(+)',
'   AND S.CLASS_ID  =CS.CLASS_ID',
'  -- AND S.STATUS=''A''',
'   AND STUDENT_ID  =:P30_STUDENT_ID_1',
'   AND S.SITE_ID   =:APP_SITE_ID'))
