,p_button_plug_id=>wwv_flow_imp.id(31172479249583568016)
,p_button_name=>'Save_Student_Fee'
,p_button_action=>'SUBMIT'
,p_button_template_options=>'#DEFAULT#:t-Button--iconLeft'
,p_button_template_id=>2082829544945815391
,p_button_is_hot=>'Y'
,p_button_image_alt=>'Save '
,p_button_position=>'CREATE'
,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_CNT NUMBER;',
'   V_PERM NUMBER;',
'BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM STUDENT_FEES S    ',
'    WHERE S.STUDENT_ID=:P30_STUDENT_ID_1',
'      AND SITE_ID=:APP_SITE_ID',
'      AND STATUS = ''I''',
'      ;',
'   SELECT COUNT(*)',
'   INTO V_PERM',
'   FROM ROLE_PERMISSIONS RP',
'   WHERE RP.ROLE_ID IN (',
'                       SELECT ROLE_ID',
'                         FROM ASSIGN_ROLE_USER',
'                        WHERE APP_USER = :APP_USER',
'                        )',
'   AND RP.PERMISSION_ID IN (9,60);',
'',
'      IF V_CNT = 0 AND V_PERM > 0 THEN',
'         RETURN TRUE;',
'      ELSE',
'         RETURN FALSE;',
'      END IF;',
' END;'))
,p_button_condition2=>'PLSQL'
,p_button_condition_type=>'FUNCTION_BODY'
,p_icon_css_classes=>'fa-save'
,p_database_action=>'INSERT'
);
