,p_validation_name=>'IF FEE RCVD IN SAME MONTH  THEN FEE NOT  CHANGE'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM STUDENT_FEE_COLLECTION ',
'    WHERE STUDENT_ID=:P30_STUDENT_ID_1',
'      AND SITE_ID=:APP_SITE_ID',
'      AND FEE_MONTH=TO_CHAR(SYSDATE,''MM-YYYY'')',
'      ;',
'  IF V_CNT > 0 THEN',
'     RETURN FALSE;',
'  ELSE',
'     RETURN TRUE;',
'  END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Current monnth fees received, delete it first or update it on next month.'
,p_when_button_pressed=>wwv_flow_imp.id(31172481991489568043)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
