,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_STUDENT VARCHAR2(20);',
'   V_STUDENT_ID NUMBER;',
'   BEGIN',
'       SELECT COUNT(*) INTO V_STUDENT',
'          FROM STUDENTS S',
'         WHERE S.STUDENT_ID = :P30_STUDENT_ID_1',
'           AND S.SITE_ID    = :APP_SITE_ID',
'           --AND S.STATUS    <> ''P''',
'           ;',
'          IF V_STUDENT = 0 AND :P30_STATUS <> ''P'' THEN',
'             SELECT NVL(MAX(STUDENT_ID),100)+1 INTO V_MAX_STUDENT_ID',
'             FROM STUDENTS S',
'            WHERE S.SITE_ID=:APP_SITE_ID',
'              AND S.STATUS <> ''P''',
'              ;',
'            :P30_STUDENT_ID_1:=V_MAX_STUDENT_ID;    ',
'         ELSIF V_STUDENT = 0 AND :P30_STATUS = ''P'' THEN     ',
'            SELECT NVL(MAX(STUDENT_ID),0)+1 INTO V_MAX_STUDENT_ID',
'             FROM STUDENTS S',
'            WHERE S.SITE_ID=:APP_SITE_ID',
'              AND S.STATUS = ''P''',
'              ;',
'            :P30_STUDENT_ID_1:=V_MAX_STUDENT_ID;    ',
'        END IF;   ',
'END;  '))
,p_attribute_02=>'P30_STUDENT_ID_1,P30_FEE_STATUS,P30_CLASS_ID'
