wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(51530279598751594113)
,p_event_id=>wwv_flow_imp.id(30767317245935546303)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_name=>'Pass Inactive Date'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_ACTIVE_DATE DATE;',
'  V_INACTIVE_DATE DATE;',
'BEGIN',
'          BEGIN',
'          SELECT ACTIVE_DATE,INACTIVE_DATE INTO V_ACTIVE_DATE,V_INACTIVE_DATE',
'            FROM STUDENTS S     ',
'           WHERE S.STUDENT_ID=:P30_STUDENT_ID_1',
'             AND S.SITE_ID   =:APP_SITE_ID',
'             ;',
'         EXCEPTION WHEN NO_DATA_FOUND THEN',
'                 V_ACTIVE_DATE:='''';',
'                 V_INACTIVE_DATE:='''';',
'         END;         ',
'        IF :P30_STATUS = ''I'' THEN',
'            :P30_INACTIVE_DATE:=TRUNC(SYSDATE);',
'            :P30_ACTIVE_DATE  :=V_ACTIVE_DATE;',
'        ELSIF :P30_STATUS = ''A'' THEN',
'            --:P30_INACTIVE_DATE:='''';',
'            :P30_ACTIVE_DATE:=V_ACTIVE_DATE;',
'            :P30_INACTIVE_DATE:=V_INACTIVE_DATE;',
'        ELSIF :P30_STATUS = ''P'' THEN',
'            --:P30_INACTIVE_DATE:='''';',
'            :P30_ACTIVE_DATE:=TRUNC(SYSDATE);',
'            :P30_INACTIVE_DATE:=V_INACTIVE_DATE;    ',
'        END IF;   ',
'END;   '))
,p_attribute_02=>'P30_FEE_STATUS,P30_STUDENT_ID_1'
,p_attribute_03=>'P30_INACTIVE_DATE,P30_ACTIVE_DATE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
