,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'STUDENT RECORD'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'SELECT STUDENT_NAME,LAST_NAME,GENDER,TO_CHAR(DATE_OF_BIRTH,''DD-MM-YYYY'')DATE_OF_BIRTH,TO_CHAR(ADMISSION_DATE,''DD-MM-YYYY'')ADMISSION_DATE,CLASS_ID,MEDICAL_CONDITION,LEARNING_NEED,',
'       STUDENT_TYPE,SCHOOL_NAME,SESSIONS,STATUS,STAGE,SIBLING_AD_NO,COMMENTS ',
'  INTO :P30_STUDENT_NAME,:P30_LAST_NAME,:P30_GENDER,:P30_DATE_OF_BIRTH,:P30_ADMISSION_DATE,:P30_CLASS_ID,:P30_MEDICAL_CONDITION,:P30_LEARNING_NEED,:P30_STUDENT_TYPE,:P30_SCHOOL_NAME,:P30_SESSIONS',
'       ,:P30_STATUS,:P30_STAGE,:P30_SIBLING_ADMISSION_NO,:P30_COMMENTS',
'  FROM STUDENTS S ',
' WHERE STUDENT_ID=:P30_STUDENT_ID_1',
'   AND SITE_ID=:APP_SITE_ID',
'   ;      ',
' EXCEPTION WHEN NO_DATA_FOUND THEN',
'    NULL;    ',
' END;',
' BEGIN',
'   SELECT STUDENT_ID,S.PARENT_ID,S.PARENT_NAME,S.RELATIONSHIP,S.CONTACT_NUMBER,EME_CONT_NUMBER,S.EME_NAME,S.EMAIL,S.OCCUPATION,S.ADDRESS,S.POSTCODE',
'     INTO :P30_STUDENT_ID_2,:P30_PARENT_ID,:P30_PARENT_NAME,:P30_RELATIONSHIP,:P30_CONTACT_NUMBER,:P30_EME_CONTACT_NUMBER,:P30_EME_NAME,:P30_EMAIL,:P30_OCCUPATION,:P30_ADDRESS,:P30_POSTCODE',
'    FROM STUDENT_PARENTS S ',
'   WHERE STUDENT_ID=:P30_STUDENT_ID_1',
'     AND SITE_ID=:APP_SITE_ID',
'   ;      ',
' EXCEPTION WHEN NO_DATA_FOUND THEN',
'  NULL;',
'END; ',
'',
'BEGIN',
' SELECT FEE_ID,REGISTRATION_FEE,REG_FEE_DISC,BOOK_FEE,EXAM_FEE,PAST_PAPER_FEE,PAST_PAPER_DISC,HOURLY_FEE,HOURLY_FEE_DISC,',
'        TOTAL_FEE,PAY_ID,FEE_START_DATE,SPECIAL_DISC,TUITION_FEE_TYPE,TUTION_TIME,TUTION_TIME,DISC_REASON,NO_OF_BOOKS,BOOK_DISC,',
'        (NVL(REGISTRATION_FEE,0)+NVL(BOOK_FEE,0)+NVL(PAST_PAPER_FEE,0)+NVL(TOTAL_FEE,0)),STATUS,DUE_DATE   ',
'    INTO :P30_FEE_ID,:P30_REGISTRATION_FEE,:P30_REG_FEE_DISC,:P30_BOOK_FEE,:P30_EXAM_FEE,:P30_PAST_PAPER_FEE,:P30_PAST_PAPER_DISC,:P30_HOURLY_FEE,:P30_HOURLY_FEE_DISC,',
'         :P30_TOTAL_FEE,:P30_PAY_ID,:P30_FEE_START_DATE,:P30_SPECIAL_DISC,:P30_TUITION_FEE_TYPE,:P30_TUTION_TIME,:P30_TUTION_TIME_HIDDEN,:P30_DISC_REASON,:P30_NO_OF_BOOKS,:P30_BOOKS_FEE_DISC,:P30_TOTAL_PAYABLE,',
'         :P30_FEE_STATUS,:P30_DUE_DATE',
'  FROM STUDENT_FEES F           ',
' WHERE F.STUDENT_ID=:P30_STUDENT_ID_1',
'   AND SITE_ID     =:APP_SITE_ID',
'   AND STATUS      =''A''',
'   ;',
'   EXCEPTION WHEN NO_DATA_FOUND THEN',
'      NULL; ',
'   END;  ',
'',
'BEGIN',
' SELECT NVL(SUM( ROUND((TO_DATE(C.END_TIME, ''HH24:MI'') - TO_DATE(C.START_TIME, ''HH24:MI'')) * 24, 2)),0) INTO :P30_TOTAL_STUDY_HOURS',
'  FROM STUDENT_CLASSES_SCHEDULE S,CLASS_SCHEDULE C',
' WHERE S.CLASS_SHEDULE_ID=C.SCHEDULE_ID ',
'   AND S.SITE_ID         =C.SITE_ID',
'   AND S.STUDENT_ID      =:P30_STUDENT_ID_1',
'   AND S.SITE_ID         =:APP_SITE_ID',
'   ;',
'EXCEPTION WHEN NO_DATA_FOUND THEN',
'  :P30_TOTAL_STUDY_HOURS:=0;',
'END;',
'',
'BEGIN',
'   SELECT REF_ID,STUDENT_ID,REF_NAME,REFRENCE_STUDENT_ID',
'     INTO :P30_REF_ID,:P30_STUDENT_ID_4,:P30_REF_NAME,:P30_REFRENCE_STUDENT_ID',
'     FROM STUDENT_REFERENCES S      ',
'    WHERE S.STUDENT_ID =:P30_STUDENT_ID_1',
'      AND S.SITE_ID=:APP_SITE_ID',
'      ;',
'   EXCEPTION WHEN NO_DATA_FOUND THEN',
'       NULL;',
'END;  ',
'        ',
'BEGIN',
'  SELECT P.CONTRACT_ID INTO :P30_PARENT_CONTRACT_ID',
'    FROM PARENTS_CONTRACT P',
'   WHERE P.STUDENT_ID = :P30_STUDENT_ID_1',
'     AND P.SITE_ID    = :APP_SITE_ID',
'     ;',
'    EXCEPTION WHEN NO_DATA_FOUND THEN',
'       NULL;',
'END;         '))
,p_attribute_02=>'P30_STUDENT_ID_1,P30_BRANCHESP30_EME_NAME'
,p_attribute_03=>'P30_STUDENT_NAME,P30_LAST_NAME,P30_GENDER,P30_DATE_OF_BIRTH,P30_ADMISSION_DATE,P30_CLASS_ID,P30_MEDICAL_CONDITION,P30_LEARNING_NEED,P30_SCHOOL_NAME,P30_SESSIONS,P30_FEE_STATUS,P30_COMMENTS,P30_PARENT_ID,P30_PARENT_NAME,P30_RELATIONSHIP,P30_CONTACT_NU'
||'MBER,P30_EMAIL,P30_OCCUPATION,P30_POSTCODE,P30_ADDRESS,P30_STUDENT_ID_2,:P30_FEE_ID,:P30_REGISTRATION_FEE,:P30_BOOK_FEE,:P30_EXAM_FEE,:P30_PAST_PAPER_FEE,:P30_HOURLY_FEE,:P30_TOTAL_FEE,:P30_PAY_ID,:P30_TOTAL_STUDY_HOURS,P30_REF_ID,P30_STUDENT_ID_4,P3'
