 p_id=>wwv_flow_imp.id(77625081012994605102)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Student Record'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_STUDENT_CNT NUMBER;',
'BEGIN',
'   SELECT COUNT(*) INTO V_STUDENT_CNT',
'     FROM STUDENTS S',
'    WHERE S.STUDENT_ID = :P30_STUDENT_ID_1',
'      AND S.SITE_ID    = :APP_SITE_ID',
'      ;  ',
'   ----INSERT OR UPDATE STUDENTS RECORD-----------------     ',
'    IF V_STUDENT_CNT = 0 THEN',
'          INSERT INTO STUDENTS(STUDENT_ID,STUDENT_NAME,GENDER,DATE_OF_BIRTH,ADMISSION_DATE,CLASS_ID,MEDICAL_CONDITION,LEARNING_NEED,SCHOOL_NAME,SITE_ID,STATUS,FEED_BY,',
'                               FEED_DATE,LAST_NAME,SESSIONS,ASSESSMENT_ID,STUDENT_TYPE,INACTIVE_DATE,ACTIVE_DATE,STAGE,SIBLING_AD_NO,COMMENTS)',
'              VALUES(:P30_STUDENT_ID_1,:P30_STUDENT_NAME,:P30_GENDER,TO_DATE(:P30_DATE_OF_BIRTH,''DD-MM-YYYY''),TO_DATE(:P30_ADMISSION_DATE,''DD-MM-YYYY''),:P30_CLASS_ID,',
'                     :P30_MEDICAL_CONDITION,:P30_LEARNING_NEED,:P30_SCHOOL_NAME,:APP_SITE_ID,:P30_STATUS,:APP_USER,TRUNC(SYSDATE),:P30_LAST_NAME,:P30_SESSIONS,:P30_ASSESSMENT_ID,',
'                     :P30_STUDENT_TYPE,:P30_INACTIVE_DATE,:P30_ACTIVE_DATE,:P30_STAGE,:P30_SIBLING_ADMISSION_NO,:P30_COMMENTS)  ',
'                     ;',
'      ELSE',
'           UPDATE STUDENTS    ',
'              SET STUDENT_NAME = :P30_STUDENT_NAME,GENDER = :P30_GENDER, DATE_OF_BIRTH = TO_DATE(:P30_DATE_OF_BIRTH,''DD-MM-YYYY''), ADMISSION_DATE = TO_DATE(:P30_ADMISSION_DATE,''DD-MM-YYYY''),',
'                  CLASS_ID = :P30_CLASS_ID, MEDICAL_CONDITION = :P30_MEDICAL_CONDITION, LEARNING_NEED = :P30_LEARNING_NEED, SCHOOL_NAME = :P30_SCHOOL_NAME,',
'                  STATUS = :P30_STATUS, FEED_BY = :APP_USER, FEED_DATE = TRUNC(SYSDATE), LAST_NAME = :P30_LAST_NAME, SESSIONS = :P30_SESSIONS,',
'                  ASSESSMENT_ID = :P30_ASSESSMENT_ID, STUDENT_TYPE = :P30_STUDENT_TYPE, INACTIVE_DATE = :P30_INACTIVE_DATE, ACTIVE_DATE = :P30_ACTIVE_DATE, STAGE = :P30_STAGE,',
'                  SIBLING_AD_NO = :P30_SIBLING_ADMISSION_NO, COMMENTS = :P30_COMMENTS',
'            WHERE STUDENT_ID = :P30_STUDENT_ID_1',
'              AND SITE_ID    = :APP_SITE_ID',
'              ;     ',
'    END IF;   ',
'END;       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST IN (''Save_Student1'', ''Save_Student1_1'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>77625081012994605102
);
