 p_id=>wwv_flow_imp.id(77625081410583605106)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Parents and others Record'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_STUDENT_CNT NUMBER;',
'  V_PARENTS_CNT NUMBER;',
'  V_FEE_CNT NUMBER;',
'  V_STUDENT_REF NUMBER;',
'BEGIN',
'   SELECT COUNT(*) INTO V_STUDENT_CNT',
'     FROM STUDENTS S',
'    WHERE S.STUDENT_ID = :P30_STUDENT_ID_1',
'      AND S.SITE_ID    = :APP_SITE_ID',
'      ;  ',
'   SELECT COUNT(*) INTO V_PARENTS_CNT',
'     FROM STUDENT_PARENTS SP',
'    WHERE SP.STUDENT_ID = :P30_STUDENT_ID_1',
'      AND SP.SITE_ID    = :APP_SITE_ID',
'      ;     ',
'   SELECT COUNT(*) INTO V_FEE_CNT',
'     FROM STUDENT_FEES SF',
'    WHERE SF.STUDENT_ID = :P30_STUDENT_ID_1',
'      AND SF.SITE_ID    = :APP_SITE_ID',
'      AND SF.STATUS     = ''A''',
'      ;  ',
'   SELECT COUNT(*) INTO V_STUDENT_REF',
'     FROM STUDENT_REFERENCES SR',
'    WHERE SR.STUDENT_ID = :P30_STUDENT_ID_1',
'      AND SR.SITE_ID    = :APP_SITE_ID',
'      ;',
'   ----INSERT OR UPDATE STUDENTS RECORD-----------------     ',
'    /*IF V_STUDENT_CNT = 0 THEN',
'          INSERT INTO STUDENTS(STUDENT_ID,STUDENT_NAME,GENDER,DATE_OF_BIRTH,ADMISSION_DATE,CLASS_ID,MEDICAL_CONDITION,LEARNING_NEED,SCHOOL_NAME,SITE_ID,STATUS,FEED_BY,',
'                               FEED_DATE,LAST_NAME,SESSIONS,ASSESSMENT_ID,STUDENT_TYPE,INACTIVE_DATE,ACTIVE_DATE,STAGE)',
'              VALUES(:P30_STUDENT_ID_1,:P30_STUDENT_NAME,:P30_GENDER,TO_DATE(:P30_DATE_OF_BIRTH,''DD-MM-YYYY''),TO_DATE(:P30_ADMISSION_DATE,''DD-MM-YYYY''),:P30_CLASS_ID,',
'                     :P30_MEDICAL_CONDITION,:P30_LEARNING_NEED,:P30_SCHOOL_NAME,:APP_SITE_ID,:P30_STATUS,:APP_USER,TRUNC(SYSDATE),:P30_LAST_NAME,:P30_SESSIONS,:P30_ASSESSMENT_ID,',
'                     :P30_STUDENT_TYPE,:P30_INACTIVE_DATE,:P30_ACTIVE_DATE,:P30_STAGE)  ',
'                     ;',
'      ELSE',
'           UPDATE STUDENTS    ',
'              SET STUDENT_NAME = :P30_STUDENT_NAME,GENDER = :P30_GENDER, DATE_OF_BIRTH = TO_DATE(:P30_DATE_OF_BIRTH,''DD-MM-YYYY''), ADMISSION_DATE = TO_DATE(:P30_ADMISSION_DATE,''DD-MM-YYYY''),',
'                  CLASS_ID = :P30_CLASS_ID, MEDICAL_CONDITION = :P30_MEDICAL_CONDITION, LEARNING_NEED = :P30_LEARNING_NEED, SCHOOL_NAME = :P30_SCHOOL_NAME,',
'                  STATUS = :P30_STATUS, FEED_BY = :APP_USER, FEED_DATE = TRUNC(SYSDATE), LAST_NAME = :P30_LAST_NAME, SESSIONS = :P30_SESSIONS,',
'                  ASSESSMENT_ID = :P30_ASSESSMENT_ID, STUDENT_TYPE = :P30_STUDENT_TYPE, INACTIVE_DATE = :P30_INACTIVE_DATE, ACTIVE_DATE = :P30_ACTIVE_DATE, STAGE = :P30_STAGE ',
'            WHERE STUDENT_ID = :P30_STUDENT_ID_1',
'              AND SITE_ID    = :APP_SITE_ID',
'              ;     ',
'    END IF;  */ ',
'  ----INSERT OR UPDATE PARENST RECORDS------------------',
'   IF V_PARENTS_CNT = 0 AND V_STUDENT_CNT > 0 AND :P30_PARENT_NAME IS NOT NULL THEN',
'      INSERT INTO STUDENT_PARENTS(STUDENT_ID,PARENT_NAME,RELATIONSHIP,CONTACT_NUMBER,EMAIL,OCCUPATION,ADDRESS,POSTCODE,STATUS,FEED_BY,FEED_DATE,SITE_ID,EME_CONT_NUMBER,',
'                                 EME_NAME)  ',
'          VALUES(:P30_STUDENT_ID_1,:P30_PARENT_NAME,:P30_RELATIONSHIP,:P30_CONTACT_NUMBER,:P30_EMAIL,:P30_OCCUPATION,:P30_ADDRESS,:P30_POSTCODE,:P30_STATUS,:APP_USER,',
'                 TRUNC(SYSDATE),:APP_SITE_ID,:P30_EME_CONTACT_NUMBER,:P30_EME_NAME)',
'                 ;                          ',
'   ELSIF V_PARENTS_CNT > 0 AND V_STUDENT_CNT > 0 THEN',
'       UPDATE STUDENT_PARENTS',
'          SET PARENT_NAME = :P30_PARENT_NAME, RELATIONSHIP = :P30_RELATIONSHIP, CONTACT_NUMBER = :P30_CONTACT_NUMBER, EMAIL = :P30_EMAIL, OCCUPATION = :P30_OCCUPATION,',
'              ADDRESS = :P30_ADDRESS, POSTCODE = :P30_POSTCODE, STATUS = :P30_STATUS, FEED_BY = :APP_USER, FEED_DATE = TRUNC(SYSDATE), EME_CONT_NUMBER = :P30_EME_CONTACT_NUMBER,',
'              EME_NAME = :P30_EME_NAME',
'         WHERE PARENT_ID = :P30_PARENT_ID',
'           AND SITE_ID   = :APP_SITE_ID  ',
'              ;',
'   END IF;',
'   ----INSERT OR UPADTE STUDENT FEE RECORD-----------------',
'   IF V_FEE_CNT = 0 AND V_STUDENT_CNT > 0 AND :P30_FEE_START_DATE IS NOT NULL THEN',
'    INSERT INTO STUDENT_FEES(STUDENT_ID,REGISTRATION_FEE,REG_FEE_DISC,BOOK_FEE,EXAM_FEE,HOURLY_FEE,PAST_PAPER_FEE,PAST_PAPER_DISC,DUE_DATE,PAY_ID,FEED_BY,FEED_DATE,',
'                                SITE_ID,TOTAL_FEE,FEE_START_DATE,HOURLY_FEE_DISC,SPECIAL_DISC,TUITION_FEE_TYPE,TUTION_TIME,BOOK_DISC,NO_OF_BOOKS,DISC_REASON,STATUS)',
'          VALUES(:P30_STUDENT_ID_1,:P30_REGISTRATION_FEE,:P30_REG_FEE_DISC,:P30_BOOK_FEE,:P30_EXAM_FEE,:P30_HOURLY_FEE,:P30_PAST_PAPER_FEE,:P30_PAST_PAPER_DISC,:P30_DUE_DATE,:P30_PAY_ID,:APP_USER,TRUNC(SYSDATE),',
'                 :APP_SITE_ID,:P30_TOTAL_FEE,:P30_FEE_START_DATE,:P30_HOURLY_FEE_DISC,:P30_SPECIAL_DISC,:P30_TUITION_FEE_TYPE,:P30_TUTION_TIME_HIDDEN,:P30_BOOKS_FEE_DISC,:P30_NO_OF_BOOKS,',
'                 :P30_DISC_REASON,:P30_FEE_STATUS)    ',
'                 ;',
'   ELSIF V_FEE_CNT > 0 AND V_STUDENT_CNT > 0 THEN                                   ',
'      UPDATE STUDENT_FEES',
'         SET REGISTRATION_FEE = :P30_REGISTRATION_FEE,REG_FEE_DISC = :P30_REG_FEE_DISC, BOOK_FEE = :P30_BOOK_FEE, EXAM_FEE = :P30_EXAM_FEE, HOURLY_FEE = :P30_HOURLY_FEE,',
'              PAST_PAPER_FEE = :P30_PAST_PAPER_FEE, PAST_PAPER_DISC = :P30_PAST_PAPER_DISC, DUE_DATE = :P30_DUE_DATE, PAY_ID = :P30_PAY_ID, FEED_BY = :APP_USER, FEED_DATE = TRUNC(SYSDATE), ',
'              TOTAL_FEE = :P30_TOTAL_FEE, FEE_START_DATE = :P30_FEE_START_DATE, HOURLY_FEE_DISC = :P30_HOURLY_FEE_DISC, SPECIAL_DISC = :P30_SPECIAL_DISC,',
'              TUITION_FEE_TYPE = :P30_TUITION_FEE_TYPE, TUTION_TIME = :P30_TUTION_TIME_HIDDEN, BOOK_DISC = :P30_BOOKS_FEE_DISC, NO_OF_BOOKS = :P30_NO_OF_BOOKS, DISC_REASON = :P30_DISC_REASON,',
'              STATUS = :P30_FEE_STATUS',
'       WHERE FEE_ID   = :P30_FEE_ID',
'         AND SITE_ID  = :APP_SITE_ID',
'       ;    ',
'   END IF;',
'   ----STUDENT REFFREAL INSERT OR UPDATE----------------------',
'   IF V_STUDENT_REF = 0 AND V_STUDENT_CNT > 0 AND :P30_REF_NAME IS NOT NULL THEN',
'      INSERT INTO STUDENT_REFERENCES(STUDENT_ID,REF_NAME,FEED_BY,FEED_DATE,SITE_ID,REFRENCE_STUDENT_ID) ',
'          VALUES(:P30_STUDENT_ID_1,:P30_REF_NAME,:APP_USER,TRUNC(SYSDATE),:APP_SITE_ID,:P30_REFRENCE_STUDENT_ID)',
'          ;',
'   ELSIF V_STUDENT_REF > 0 AND V_STUDENT_CNT > 0 THEN',
'     UPDATE STUDENT_REFERENCES',
'        SET REF_NAME = :P30_REF_NAME, FEED_BY = :APP_USER, FEED_DATE = TRUNC(SYSDATE), REFRENCE_STUDENT_ID = :P30_REFRENCE_STUDENT_ID  ',
'      WHERE STUDENT_ID = :P30_STUDENT_ID_1',
'        AND SITE_ID    = :APP_SITE_ID',
'        ;',
'   END IF;          ',
'END;       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST IN (''Save_Student1'', ''Save_Student1_1'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>77625081410583605106
);
