,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P30_ASSESSMENT_ID IS NOT NULL THEN',
'    /*INSERT INTO STUDENT_PARENTS(STUDENT_ID,SITE_ID,PARENT_NAME,RELATIONSHIP,CONTACT_NUMBER,OCCUPATION,ADDRESS,POSTCODE,STATUS,FEED_BY,FEED_DATE)',
'    SELECT :P30_STUDENT_ID,:P30_SITE_ID,SA.PARENT_NAME,RELATION,CONTACT_NO,OCCUPATION,ADDRESS,POSTCODE,''A'',:APP_USER,TRUNC(SYSDATE)',
'      FROM STUDENT_ASSESSMENT SA',
'     WHERE SA.ASSESSMENT_ID=:P30_ASSESSMENT_ID',
'     ;    */              ',
'     INSERT INTO STUDENT_ADMISSION_TEST(STUDENT_ID,SITE_ID,TEST_DATE,BOOK_ID,SUBJECT_ID,TOTAL_MARKS,OBTAINED_MARKS,SCORE,GRADE,FEED_BY,FEED_DATE)',
'     SELECT :P30_STUDENT_ID_1,:P30_SITE_ID,ASSESSMENT_DATE,BOOK_ID,SUBJECT_ID,S.TOTAL_MARKS,S.OBTAINED_MARK,SCORE,GRADE,:APP_USER,TRUNC(SYSDATE)',
'       FROM STUDENT_ASSESSMENT SA,STUDENT_ASSESSMENT_BOOK_RESULT S',
'      WHERE SA.ASSESSMENT_ID=S.ASSESSMENT_ID',
'        AND S.ASSESSMENT_ID=:P30_ASSESSMENT_ID',
'     ;  ',
' END IF;                   '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST IN (''Save_Student1'', ''Save_Student1_1'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>30808190128139263111
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(31172479136697568015)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(30808193701864263147)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Student Assessment Result - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
' BEGIN',
'    CASE :apex$row_status',
'      WHEN ''C'' THEN',
'      -- IF :SUBJECT_ID IS NOT NULL OR :SCORE IS NOT NULL THEN',
'          INSERT INTO STUDENT_ADMISSION_TEST(STUDENT_ID,TEST_DATE,CLASS_ID,SUBJECT_ID,BOOK_ID,TOTAL_MARKS,OBTAINED_MARKS,SCORE,GRADE,SITE_ID,FEED_BY,FEED_DATE)',
'            VALUES(:P30_STUDENT_ID_1,:TEST_DATE,:CLASS_ID,:SUBJECT_ID,:BOOK_ID,:TOTAL_MARKS,:OBTAINED_MARKS,:SCORE,:GRADE,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE))',
'            ;',
'       --END IF;     ',
'        WHEN ''U'' THEN',
'        -- IF :SUBJECT_ID IS NOT NULL OR :SCORE IS NOT NULL THEN',
'            UPDATE STUDENT_ADMISSION_TEST',
'            SET TEST_DATE            =:TEST_DATE,',
'                CLASS_ID             =:CLASS_ID,',
'                SUBJECT_ID           =:SUBJECT_ID,',
'                BOOK_ID              =:BOOK_ID,',
'                TOTAL_MARKS          =:TOTAL_MARKS,',
'                OBTAINED_MARKS       =:OBTAINED_MARKS,',
'                SCORE                =:SCORE,',
'                GRADE                =:GRADE,',
'                FEED_BY              =:APP_USER,',
'                FEED_DATE            =TRUNC(SYSDATE)',
'            WHERE TEST_ID            = :TEST_ID    ',
'            ;',
'         -- END IF;   ',
'        WHEN ''D'' THEN',
'            DELETE FROM STUDENT_ADMISSION_TEST',
'            WHERE TEST_ID   = :TEST_ID    ',
'            ;    ',
'    END CASE;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(31678745706498883526)
,p_internal_uid=>31172479136697568015
);
