,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'HOC / MEETINGS - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_COMMENTS NUMBER;',
' BEGIN',
'    SELECT NVL(MAX(COMMENTS_NO),0)+1 INTO V_COMMENTS',
'      FROM STUDENT_MEETING_COMMENTS S',
'     WHERE S.STUDENT_ID=:P30_STUDENT_ID_1',
'       AND S.SITE_ID   =:APP_SITE_ID',
'       ; ',
'',
'    CASE :apex$row_status',
'      WHEN ''C'' THEN',
'          INSERT INTO STUDENT_MEETING_COMMENTS(STUDENT_ID,MEETING_DATE,COMMENTS,COMMENTS_NO,SITE_ID,FEED_BY,FEED_DATE)',
'            VALUES(:P30_STUDENT_ID_1,:MEETING_DATE,:COMMENTS,V_COMMENTS,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE))',
'            ;',
'        WHEN ''U'' THEN',
'            UPDATE STUDENT_MEETING_COMMENTS',
'            SET COMMENTS     =:COMMENTS,',
'                MEETING_DATE =:MEETING_DATE,',
'                FEED_BY      =:APP_USER,',
'                FEED_DATE    =TRUNC(SYSDATE)',
'            WHERE COMMENT_ID = :COMMENT_ID    ',
'            ;',
'        WHEN ''D'' THEN',
'            DELETE FROM STUDENT_MEETING_COMMENTS',
'            WHERE COMMENT_ID   = :COMMENT_ID    ',
'            ;    ',
'    END CASE;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(31678745706498883526)
,p_internal_uid=>31612497955967900411
);
