'       --END IF;     ',
'        WHEN ''U'' THEN',
'       --IF :CLASS_ID IS NOT NULL OR :SUBJECT_ID IS NOT NULL OR :BOOK_ID IS NOT NULL OR :WEEKDAY IS NOT NULL OR :START_TIME IS NOT NULL ',
'       --  OR :END_TIME IS NOT NULL OR :CLASS_SHEDULE_ID IS NOT NULL THEN ',
'            UPDATE STUDENT_CLASSES_SCHEDULE',
'            SET CLASS_SHEDULE_ID =:CLASS_SHEDULE_ID,',
'                STATUS           =:STATUS,',
'                FEED_BY          =:APP_USER,',
'                FEED_DATE        =TRUNC(SYSDATE)',
'            WHERE STUDENT_SCHEDULE_ID = :STUDENT_SCHEDULE_ID    ',
'            ;',
'      -- END IF;     ',
'        WHEN ''D'' THEN',
'            DELETE FROM STUDENT_CLASSES_SCHEDULE',
'            WHERE STUDENT_SCHEDULE_ID   = :STUDENT_SCHEDULE_ID    ',
'            ;    ',
'    END CASE;',
'END;',
'',
''))
