,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_CLASS_STAGE VARCHAR2(1);',
'  BEGIN',
'  IF :P31_CLASS_ID IS NOT NULL THEN',
'     SELECT SUBSTR(STAGE_TYPE,1,1) INTO V_CLASS_STAGE',
'       FROM CLASSES',
'      WHERE CLASS_ID=:P31_CLASS_ID',
'      ;  ',
'      IF V_CLASS_STAGE=''K'' THEN',
'        SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),300)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'           AND S.SITE_ID=:APP_SITE_ID ',
'        ;',
'      ELSIF V_CLASS_STAGE=''G'' THEN',
'           SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),500)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'           AND S.SITE_ID=:APP_SITE_ID ',
'         ;',
'      ELSIF V_CLASS_STAGE=''A'' THEN',
'           SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),100)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'           AND S.SITE_ID=:APP_SITE_ID ',
'     ;       ',
'    END IF;',
'       :P31_STUDENT_ID:=V_CLASS_STAGE||V_MAX_STUDENT_ID;',
' END IF; ',
'END;  '))
,p_attribute_02=>'APP_SITE_ID,P31_CLASS_ID'
,p_attribute_03=>'P31_STUDENT_ID'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
