wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(100057435163159980901)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate Student ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_CLASS_STAGE VARCHAR2(1);',
'   V_NEW_STUDENT_ID VARCHAR2(20);',
'  BEGIN',
'       IF :P31_CLASS_ID IS NOT NULL AND :P31_STATUS = ''A'' THEN',
'      ',
'            SELECT NVL(MAX(STUDENT_ID),100)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE  S.SITE_ID=:APP_SITE_ID ',
'             ;',
'           V_NEW_STUDENT_ID:=V_MAX_STUDENT_ID;  ',
'',
'           INSERT INTO STUDENTS(STUDENT_ID,STUDENT_NAME,LAST_NAME,STUDENT_TYPE,GENDER,DATE_OF_BIRTH,ADMISSION_DATE,CLASS_ID,MEDICAL_CONDITION,',
'                                 LEARNING_NEED,SESSIONS,ASSESSMENT_ID,SITE_ID,STATUS,FEED_BY,FEED_DATE,ACTIVE_DATE,INACTIVE_DATE,STAGE)',
'           VALUES  (V_NEW_STUDENT_ID,:P31_STUDENT_NAME,:P31_LAST_NAME,:P31_STUDENT_TYPE,:P31_GENDER,:P31_DATE_OF_BIRTH,:P31_ADMISSION_DATE,:P31_CLASS_ID,:P31_MEDICAL_CONDITION,',
'                   :P31_LEARNING_NEED,:P31_SESSIONS,:P31_ASSESSMENT,:APP_SITE_ID,''A'',:APP_USER,TRUNC(SYSDATE),:P31_ACTIVE_DATE,:P31_INACTIVE_DATE,:P31_STAGE)',
'              ;',
'           INSERT INTO  STUDENT_PARENTS(STUDENT_ID,PARENT_NAME,RELATIONSHIP,CONTACT_NUMBER,EMAIL,OCCUPATION,ADDRESS,POSTCODE,STATUS,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT V_NEW_STUDENT_ID,PARENT_NAME,RELATIONSHIP,CONTACT_NUMBER,EMAIL,OCCUPATION,ADDRESS,POSTCODE,STATUS,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                FROM  STUDENT_PARENTS',
'                WHERE STUDENT_ID = :P31_STUDENT_ID',
'                AND   SITE_ID    = :APP_SITE_ID',
'                ;',
'           /*',
'           INSERT INTO STUDENT_EMERGENCY_CONTACTS (STUDENT_ID,CONTACT_NAME,RELATIONSHIP,CONTACT_NUMBER,ALTERNATE_NUMBER,ADDRESS,STATUS,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT  V_NEW_STUDENT_ID,CONTACT_NAME,RELATIONSHIP,CONTACT_NUMBER,ALTERNATE_NUMBER,ADDRESS,STATUS,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                FROM STUDENT_EMERGENCY_CONTACTS',
'                WHERE STUDENT_ID = :P31_STUDENT_ID',
'                AND SITE_ID      = :APP_SITE_ID',
'                ;*/',
'                ',
'           INSERT INTO STUDENT_REFERENCES(STUDENT_ID,REF_NAME,REFRENCE_STUDENT_ID,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT V_NEW_STUDENT_ID,REF_NAME,REFRENCE_STUDENT_ID,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                FROM STUDENT_REFERENCES',
'                WHERE STUDENT_ID = :P31_STUDENT_ID',
'                AND   SITE_ID    = :APP_SITE_ID',
'                ;',
'                ',
'           INSERT INTO STUDENT_ADMISSION_TEST(STUDENT_ID,TEST_DATE,SUBJECT_ID,SCORE,GRADE,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT V_NEW_STUDENT_ID,TEST_DATE,SUBJECT_ID,SCORE,GRADE,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                FROM STUDENT_ADMISSION_TEST ',
'                WHERE STUDENT_ID=:P31_STUDENT_ID',
'                AND SITE_ID=:APP_SITE_ID    ',
'              ;',
'           INSERT INTO STUDENT_CLASSES_SCHEDULE(STUDENT_ID,CLASS_SHEDULE_ID,SUBJECT_ID,BOOK_ID,CLASS_ID,STATUS,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT V_NEW_STUDENT_ID,CLASS_SHEDULE_ID,SUBJECT_ID,BOOK_ID,CLASS_ID,STATUS,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                 FROM STUDENT_CLASSES_SCHEDULE',
'                 WHERE STUDENT_ID = :P31_STUDENT_ID',
'                 AND   SITE_ID    = :APP_SITE_ID',
'                 ;',
'           INSERT INTO STUDENT_FEES(STUDENT_ID,REGISTRATION_FEE,BOOK_FEE,EXAM_FEE,HOURLY_FEE,PAST_PAPER_FEE,DUE_DATE,PAY_ID,TOTAL_FEE,',
'                                    FEE_START_DATE,REG_FEE_DISC,PAST_PAPER_DISC,HOURLY_FEE_DISC,SPECIAL_DISC,TUITION_FEE_TYPE,TUTION_TIME,',
'                                   DISC_REASON,SIBLING_DISC_PER,BOOK_DISC,NO_OF_BOOKS,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT V_NEW_STUDENT_ID,REGISTRATION_FEE,BOOK_FEE,EXAM_FEE,HOURLY_FEE,PAST_PAPER_FEE,DUE_DATE,PAY_ID,TOTAL_FEE,',
'                     FEE_START_DATE,REG_FEE_DISC,PAST_PAPER_DISC,HOURLY_FEE_DISC,SPECIAL_DISC,',
'                     TUITION_FEE_TYPE,TUTION_TIME,DISC_REASON,SIBLING_DISC_PER,BOOK_DISC,NO_OF_BOOKS,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                 FROM STUDENT_FEES',
'                 WHERE STUDENT_ID = :P31_STUDENT_ID',
'                 AND   SITE_ID    = :APP_SITE_ID',
'              ;',
'           INSERT INTO STUDENT_MEETING_COMMENTS (STUDENT_ID,COMMENTS,COMMENTS_NO,SITE_ID,FEED_BY,FEED_DATE)',
'              SELECT V_NEW_STUDENT_ID,COMMENTS,COMMENTS_NO,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE)',
'                FROM STUDENT_MEETING_COMMENTS ',
'                WHERE STUDENT_ID = :P31_STUDENT_ID',
'                AND   SITE_ID    = :APP_SITE_ID',
'              ;',
'                ',
'     DELETE STUDENT_FEES  ',
'      WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID=:APP_SITE_ID',
'        ;',
'      DELETE STUDENT_MEETING_COMMENTS',
'       WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID=:APP_SITE_ID',
'        ;',
'     DELETE STUDENT_CLASSES_SCHEDULE',
'      WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID=:APP_SITE_ID',
'        ;    ',
'     DELETE STUDENT_ADMISSION_TEST',
'      WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID=:APP_SITE_ID',
'        ;    ',
'     DELETE STUDENT_REFERENCES',
'      WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID=:APP_SITE_ID',
'        ;    ',
'     DELETE STUDENT_EMERGENCY_CONTACTS',
'      WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID=:APP_SITE_ID',
'        ;     ',
'    DELETE FROM STUDENT_PARENTS',
'     WHERE STUDENT_ID=:P31_STUDENT_ID',
'       AND SITE_ID=:APP_SITE_ID',
'       ;    ',
'     DELETE FROM STUDENTS   ',
'      WHERE STUDENT_ID=:P31_STUDENT_ID',
'        AND SITE_ID   =:APP_SITE_ID',
'        ;  ',
' END IF; ',
'END;  '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM STUDENTS S',
'    WHERE STUDENT_ID=:P31_STUDENT_ID',
'      AND SITE_ID=:APP_SITE_ID',
'      AND STATUS=''P''',
'      ;',
'    IF V_CNT > 0 THEN',
'      RETURN TRUE;',
'    ELSE',
'       RETURN FALSE;',
'    END IF;',
'END ;              '))
,p_process_when_type=>'FUNCTION_BODY'
,p_process_when2=>'PLSQL'
,p_process_success_message=>'Student Status Changed.'
,p_internal_uid=>100057435163159980901
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(52380898850497680670)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(121322449018138801461)
,p_process_type=>'NATIVE_FORM_DML'
