wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(39982862141058300530)
,p_validation_name=>'Stop Duplicate record'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'  V_STATUS VARCHAR2(5);',
'BEGIN',
'   SELECT COUNT(*) into V_CNT',
'     FROM TEACHER_ASSIGN_TO_STUDENT T    ',
'    WHERE T.STUDENT_CLASS_SCHEDULE_ID=:P45_STUDENT_CLASS_SCHEDULE_ID',
'      AND T.SITE_ID                  =:APP_SITE_ID',
'      ;',
'    BEGIN',
'       SELECT V_STATUS into V_STATUS',
'         FROM TEACHER_ASSIGN_TO_STUDENT T    ',
'        WHERE T.STUDENT_CLASS_SCHEDULE_ID=:P45_STUDENT_CLASS_SCHEDULE_ID',
'          AND T.SITE_ID                  =:APP_SITE_ID',
'          ;  ',
'        EXCEPTION WHEN NO_DATA_FOUND THEN  ',
'           V_STATUS:=NULL;',
'     END',
'     ;        ',
'      IF V_CNT > 0 AND V_STATUS=:P45_STATUS THEN   ',
'         RETURN FALSE;',
'      ELSE',
'         RETURN TRUE;',
'      END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Teacher already assign, You cant assign it again.'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
