'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(19412977803173212728)
,p_plug_name=>'Lesson Plan Report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SERIAL_NO,EMP_ID,ASSIGN_ID,EMP_NAME,STUDENT_ID,STUDENT_NAME,BRANCH,CLASS_NAME, BOOK,SUBJECT,WEEKDAY,START_TIME,END_TIME,ASSIGN_DATE,STATUS,FEED_BY,FEED_DATE',
'  FROM(',
'select DENSE_RANK() OVER (',
'         ORDER BY T.EMP_ID, CLS.WEEKDAY',
'       ) SERIAL_NO,',
'       T.EMP_ID,',
'       T.ASSIGN_ID,',
'       E.EMP_NAME||'' ''||E.LAST_NAME EMP_NAME,',
'       STS.STAGE||''-''||STS.STUDENT_ID STUDENT_ID,',
'       STS.STUDENT_NAME||'' ''||STS.LAST_NAME STUDENT_NAME,',
'       ST.SITE_NAME BRANCH,',
'       CS.CLASS_NAME,',
'       B.BOOK_NAME BOOK,',
'       SS.SUBJECT_NAME SUBJECT,',
'       CLS.WEEKDAY,',
'       CLS.START_TIME,',
'       CLS.END_TIME,',
'       T.ASSIGN_DATE,',
'       T.STATUS,',
'       T.FEED_BY,',
'       T.FEED_DATE',
'  from TEACHER_ASSIGN_TO_STUDENT T,STUDENT_CLASSES_SCHEDULE S,EMPLOYEES E,SITES ST,CLASSES CS,CLASS_SCHEDULE CLS,BOOKS B,SUBJECTS SS,STUDENTS STS',
'  WHERE T.STUDENT_CLASS_SCHEDULE_ID = S.STUDENT_SCHEDULE_ID',
'    AND T.SITE_ID                   = S.SITE_ID',
'    AND T.EMP_ID                    = E.EMP_ID',
'    AND T.SITE_ID                   = ST.SITE_ID',
'    AND T.CLASS_ID                  = CS.CLASS_ID',
'    AND S.CLASS_SHEDULE_ID          = CLS.SCHEDULE_ID',
'    AND S.SITE_ID                   = CLS.SITE_ID',
'    AND S.BOOK_ID                   = B.BOOK_ID(+)',
'    AND S.SUBJECT_ID                = SS.SUBJECT_ID',
'    AND T.STUDENT_ID                = STS.STUDENT_ID',
'    AND T.SITE_ID                   = STS.SITE_ID',
'    AND T.STATUS                    = ''A''',
'    AND S.STATUS                    = ''A''',
'    AND STS.STATUS                  = ''A''',
'    AND CS.STATUS                   = ''A''',
'    AND T.EMP_ID                    = NVL(:P46_EMPLOYEE_ID,T.EMP_ID)    ',
'    AND T.STUDENT_ID                = NVL(:P46_STUDENT_ID,T.STUDENT_ID)   ',
'    AND S.SUBJECT_ID                = NVL(:P46_SUBJECT,S.SUBJECT_ID)',
'    AND NVL(S.BOOK_ID,0)            = NVL(:P46_BOOK,NVL(S.BOOK_ID,0))',
'    AND UPPER(CLS.WEEKDAY)          = NVL(UPPER(:P46_WEEKDAY),UPPER(CLS.WEEKDAY))',
'    AND CLS.START_TIME              = NVL(:P46_START_TIME,CLS.START_TIME)',
'    AND CLS.END_TIME                = NVL(:P46_END_TIME,CLS.END_TIME)',
'    AND T.SITE_ID                   = :APP_SITE_ID --P46_BRANCHES',
'     /*ORDER BY    CASE',
'        WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'        WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'        WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'      END,TO_DATE(CLS.START_TIME, ''HH24:MI'') ASC*/',
'     ',
'  )',
'  ORDER BY SERIAL_NO ASC,TO_DATE(START_TIME, ''HH24:MI'') ASC',
' ',
''))
,p_plug_source_type=>'NATIVE_IR'
