wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(96629531526993195673)
,p_name=>'Master Records'
,p_template=>3371237801798025892
,p_display_sequence=>30
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ROW_NUMBER() OVER (',
'        order by  ',
'            CASE WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'                 WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'                 WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'            END,',
'            LENGTH(STUDENT_ID),',
'            STUDENT_ID',
'    ) serial#,',
'    "STUDENT_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P48_STUDENT_ID_1'', p_values => "STUDENT_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P48_STUDENT_ID_1,''0'') = "STUDENT_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'   /* TO_CHAR(ROWNUM) || ''. '' || (substr("STUDENT_ID", 1, 50) || ',
'    (substr("STUDENT_ID", 1, 50)||( case when length("STUDENT_ID") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("STUDENT_NAME", 1, 50)||( case when length("STUDENT_NAME") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE*/',
' TO_CHAR(',
'        ROW_NUMBER() OVER (',
'            order by  ',
'                CASE WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'                     WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'                     WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'                END,',
'                LENGTH(STUDENT_ID),',
'                STUDENT_ID',
'        )',
'    ) || ''. '' || ',
'    (substr("STUDENT_ID", 1, 50) || ',
'     (case when length("STUDENT_ID") > 50 then ''...'' else '''' end)) LIST_TITLE,',
'    (substr("STUDENT_NAME"||'' ''||"LAST_NAME", 1, 100) || ',
'     (case when length("STUDENT_NAME"||'' ''||"LAST_NAME") > 100 then ''...'' else '''' end)) LIST_TEXT,',
'    null LIST_BADGE',
'from "STUDENTS" x',
'where (:P48_SEARCH is null',
'        or upper(x."STUDENT_ID") like ''%''||upper(:P48_SEARCH)||''%''',
'        or upper(x."STUDENT_NAME"||'' ''||"LAST_NAME") like ''%''||upper(:P48_SEARCH)||''%''',
'    )',
'AND SITE_ID=:APP_SITE_ID    ',
'AND STATUS = ''A''',
'order by  CASE',
'            WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'            WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'            WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'          END,LENGTH(STUDENT_ID),STUDENT_ID',
'                                          ;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P48_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>2093604263195414824
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'<div class="u-tC">No data found.</div>'
,p_query_row_count_max=>500
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
