,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_CLASS_STAGE VARCHAR2(1);',
'   V_STUDENT VARCHAR2(20);',
'   BEGIN',
'   IF :P48_STATUS = ''P'' THEN  -----------------------------IN PENDING-------------------',
'      SELECT COUNT(*) INTO V_STUDENT',
'        FROM STUDENTS S',
'       WHERE STUDENT_ID=:P48_STUDENT_ID_1',
'         AND SITE_ID=:APP_SITE_ID',
'        ; ',
'        /*  ',
'        SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),100)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE SUBSTR(STUDENT_ID,1,1)=''P''',
'           AND S.SITE_ID=:APP_SITE_ID ',
'        ;  ',
'        */',
'        SELECT NVL(MAX(STUDENT_ID),100)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE  S.SITE_ID=:APP_SITE_ID ',
'         ;',
'    ELSIF :P48_CLASS_ID IS NOT NULL AND (:P48_STATUS <> ''P'') THEN---------------WITHOUT PENDINGS-----------------',
'      SELECT COUNT(*) INTO V_STUDENT',
'        FROM STUDENTS S',
'       WHERE STUDENT_ID=:P48_STUDENT_ID_1',
'         AND SITE_ID=:APP_SITE_ID',
'    ;   ',
'       /*',
'         SELECT SUBSTR(STAGE_TYPE,1,1) INTO V_CLASS_STAGE',
'           FROM CLASSES',
'          WHERE CLASS_ID=:P48_CLASS_ID',
'          ;  ',
'          IF V_CLASS_STAGE=''K'' THEN',
'            SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),300)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'               AND S.SITE_ID=:APP_SITE_ID ',
'            ;',
'          ELSIF V_CLASS_STAGE=''G'' THEN',
'               SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),500)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'               AND S.SITE_ID=:APP_SITE_ID ',
'             ;',
'          ELSIF V_CLASS_STAGE=''A'' THEN',
'               SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),100)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'               AND S.SITE_ID=:APP_SITE_ID ',
'         ;       ',
'        END IF;',
'        */',
'         SELECT NVL(MAX(STUDENT_ID),100)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE  S.SITE_ID=:APP_SITE_ID ',
'         ;',
'     ELSE',
'           :P48_STUDENT_ID_1:='''';',
'     END IF;   ',
'        /* IF :P48_CLASS_ID IS NOT NULL AND V_STUDENT=0 AND (:P48_STATUS <>''P'') THEN  ',
'            :P48_STUDENT_ID_1:=V_CLASS_STAGE||V_MAX_STUDENT_ID;',
'         ELSIF V_STUDENT = 0 AND :P48_STATUS =''P'' THEN  ',
'           :P48_STUDENT_ID_1:=''P''||V_MAX_STUDENT_ID;  ',
'        END IF; ',
'        */',
'        :P48_STUDENT_ID_1:=V_MAX_STUDENT_ID;            ',
'END;  '))
,p_attribute_02=>'P48_STUDENT_ID_1,P48_STATUS,P48_CLASS_ID'
,p_attribute_03=>'P48_STUDENT_ID_1'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
,p_da_action_comment=>'pehly stage k hisab sy lag rahi thi student id ab sequence lag gya ha ab k g or a wala seen khatam ho gya ha or pending ki surat me p b khatam ho gy aha is liye is ko rok dia ha.'
);
