wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(22162712711533003305)
,p_validation_name=>'Stop Fee Delete or update min UPDATE'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_FEE_ID NUMBER;',
'BEGIN   ',
'   SELECT NVL(MAX(FEE_COLLECTION_ID),0) INTO  V_FEE_ID',
'     FROM STUDENT_FEE_COLLECTION SFC',
'    WHERE SFC.STUDENT_ID=:P49_STUDENT_ID ',
'      AND SFC.SITE_ID   =:P49_SITE_ID',
'      ;',
'      IF V_FEE_ID=:P49_FEE_COLLECTION_ID THEN',
'         RETURN TRUE;',
'      ELSE',
'          RETURN FALSE;',
'      END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'You cannot update this fee entry because a newer fee record already exists. Please update the latest record instead.'
,p_when_button_pressed=>wwv_flow_imp.id(22029135443866020610)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
