wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(31678743438447883503)
,p_validation_name=>'Stop insert more then 2'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN   ',
'   SELECT NVL(MAX(PAYMENT_COUNT),0) INTO  V_CNT',
'     FROM STUDENT_FEE_COLLECTION SFC',
'    WHERE SFC.STUDENT_ID=:P49_STUDENT_ID ',
'      AND SFC.SITE_ID   =:P49_SITE_ID',
'      AND SFC.FEE_MONTH =:P49_FEE_MONTH',
'      ;',
'      IF V_CNT=3 THEN',
'         RETURN FALSE;',
'      ELSE',
'          RETURN TRUE;',
'      END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'You cannot insert more then 2 payment counts.'
,p_when_button_pressed=>wwv_flow_imp.id(22029135811460020610)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(38798440050741406911)
,p_validation_name=>'Stop insert more IF PREVIOUS FEE NOT FOUND'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'  V_ADM_DATE  DATE;',
'  V_FEE_DATE  DATE;',
'BEGIN   ',
' V_FEE_DATE := TO_DATE(:P49_FEE_MONTH, ''MM-YYYY'');',
'',
'   SELECT COUNT(*) INTO  V_CNT',
'     FROM STUDENT_FEE_COLLECTION SFC',
'    WHERE SFC.STUDENT_ID=:P49_STUDENT_ID ',
'      AND SFC.SITE_ID   =:P49_SITE_ID',
'      AND SFC.FEE_MONTH =TO_CHAR(ADD_MONTHS(V_FEE_DATE, -1),''MM-YYYY'')',
'      ;',
'      SELECT ADMISSION_DATE INTO V_ADM_DATE',
'        FROM STUDENTS S',
'       WHERE S.STUDENT_ID=:P49_STUDENT_ID ',
'         AND S.SITE_ID   =:P49_SITE_ID',
'         ;',
'     IF TO_CHAR(V_FEE_DATE, ''MM-YYYY'') < TO_CHAR(V_ADM_DATE, ''MM-YYYY'') THEN',
'      RETURN FALSE;',
'',
'  -- Check if previous month fee is missing (and student was already admitted)',
'    ELSIF V_CNT = 0 AND TO_CHAR(V_ADM_DATE, ''MM-YYYY'') < TO_CHAR(V_FEE_DATE, ''MM-YYYY'') THEN',
'      RETURN FALSE;',
'    ELSE',
'      RETURN TRUE;',
'    END IF;    ',
'    /*  IF V_CNT = 0  AND TO_CHAR(V_ADM_DATE,''MM-YYYY'') < TO_CHAR(V_FEE_DATE,''MM-YYYY'') THEN',
'         RETURN FALSE;',
'      ELSE',
'          RETURN TRUE;',
'      END IF;',
'      */',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Please received previous month fee first or you choose wrong fee month'
,p_validation_condition_type=>'NEVER'
,p_when_button_pressed=>wwv_flow_imp.id(22029135811460020610)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(39308967655493383402)
,p_validation_name=>'Stop insert more IF PREVIOUS FEE NOT FOUND_1'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'  V_ADM_DATE  DATE;',
'  V_FEE_DATE  DATE;',
'BEGIN   ',
' V_FEE_DATE := TO_DATE(:P49_FEE_MONTH, ''MM-YYYY'');',
'',
'   SELECT COUNT(*) INTO  V_CNT',
'     FROM STUDENT_FEE_COLLECTION SFC',
'    WHERE SFC.STUDENT_ID=:P49_STUDENT_ID ',
'      AND SFC.SITE_ID   =:P49_SITE_ID',
'      AND SFC.FEE_MONTH =TO_CHAR(ADD_MONTHS(V_FEE_DATE, -1),''MM-YYYY'')',
'      ;',
'      SELECT ADMISSION_DATE INTO V_ADM_DATE',
'        FROM STUDENTS S',
'       WHERE S.STUDENT_ID=:P49_STUDENT_ID ',
'         AND S.SITE_ID   =:P49_SITE_ID',
'         ;',
'     IF TO_CHAR(V_FEE_DATE, ''MM-YYYY'') < TO_CHAR(V_ADM_DATE, ''MM-YYYY'') THEN',
'      RETURN FALSE;',
'',
'  -- Check if previous month fee is missing (and student was already admitted)',
'    ELSIF V_CNT = 0 AND TO_CHAR(V_ADM_DATE, ''MM-YYYY'') < TO_CHAR(V_FEE_DATE, ''MM-YYYY'') THEN',
'      RETURN FALSE;',
'    ELSE',
'      RETURN TRUE;',
'    END IF;    ',
'    /*  IF V_CNT = 0  AND TO_CHAR(V_ADM_DATE,''MM-YYYY'') < TO_CHAR(V_FEE_DATE,''MM-YYYY'') THEN',
'         RETURN FALSE;',
'      ELSE',
'          RETURN TRUE;',
'      END IF;',
'      */',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Please received previous month fee first or you choose wrong fee month'
,p_validation_condition_type=>'NEVER'
,p_when_button_pressed=>wwv_flow_imp.id(22029135443866020610)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
