wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(21769941504302508717)
,p_event_id=>wwv_flow_imp.id(21769941451153508716)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P49_FEE_COLLECTION_ID IS NULL THEN',
'DECLARE',
'   V_PRV_FEE NUMBER;',
'    V_CL_BAL NUMBER;',
'  BEGIN ',
'    BEGIN',
'      SELECT  CASE',
'               WHEN TO_CHAR(SF.FEE_START_DATE,''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'') AND MAX(sfc1.FEE_MONTH) IS NULL THEN',
'                    GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, sf.FEE_START_DATE)), 0) * sf.TOTAL_FEE',
'                WHEN TO_CHAR(SF.FEE_START_DATE,''MM-YYYY'') <> TO_CHAR(SYSDATE,''MM-YYYY'') AND MAX(sfc1.FEE_MONTH) IS NULL THEN  ',
'                 -- GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, sf.FEE_START_DATE)+1), 0) * sf.TOTAL_FEE  ',
'                  GREATEST(TRUNC(MONTHS_BETWEEN(TRUNC(SYSDATE,''MM''), sf.FEE_START_DATE)+1), 0) * sf.TOTAL_FEE',
'                WHEN sT.INACTIVE_DATE IS NOT NULL AND sT.ACTIVE_DATE IS NOT NULL',
'                     AND sT.INACTIVE_DATE > TO_DATE(MAX(sfc1.FEE_MONTH), ''MM-YYYY'') AND TO_CHAR(ST.INACTIVE_DATE,''MM-YYYY'') >= TO_CHAR(sT.ACTIVE_DATE,''MM-YYYY'') THEN',
'                              0 * sf.TOTAL_FEE',
'                WHEN sT.INACTIVE_DATE IS NOT NULL AND sT.ACTIVE_DATE IS NOT NULL',
'                     AND sT.ACTIVE_DATE > TO_DATE(MAX(sfc1.FEE_MONTH), ''MM-YYYY'') AND TO_CHAR(sT.ACTIVE_DATE,''MM-YYYY'') >= TO_CHAR(ST.INACTIVE_DATE,''MM-YYYY'') THEN',
'                    --GREATEST(TRUNC(MONTHS_BETWEEN(sT.ACTIVE_DATE, TO_DATE(MAX(sfc1.FEE_MONTH), ''MM-YYYY''))) - 1, 0) * sf.TOTAL_FEE',
'                     GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, st.ACTIVE_DATE)), 0) * sf.TOTAL_FEE',
'                ELSE',
'                   GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, TO_DATE(MAX(sfc1.FEE_MONTH), ''MM-YYYY''))) - 1, 0) * sf.TOTAL_FEE',
'            END AS DUE_AMOUNT INTO V_PRV_FEE',
'        FROM STUDENTS st',
'        JOIN STUDENT_FEES sf ',
'            ON sf.STUDENT_ID = st.STUDENT_ID AND sf.SITE_ID = st.SITE_ID',
'        LEFT JOIN STUDENT_FEE_COLLECTION sfc1 ',
'             ON sfc1.STUDENT_ID = st.STUDENT_ID AND sfc1.SITE_ID = st.SITE_ID',
'        WHERE st.STUDENT_ID = :P49_STUDENT_ID',
'          AND st.SITE_ID    = :APP_SITE_ID',
'        GROUP BY st.STUDENT_ID, sf.TOTAL_FEE, st.INACTIVE_DATE, st.ACTIVE_DATE, SF.FEE_START_DATE',
'        ;',
'        EXCEPTION  WHEN NO_DATA_FOUND THEN',
'              V_PRV_FEE:=0;',
'     END',
'     ;    ',
'      BEGIN',
'        SELECT CLOSING_BALANCE INTO V_CL_BAL',
'        FROM STUDENT_FEE_COLLECTION',
'        WHERE STUDENT_ID = :P49_STUDENT_ID ',
'          AND SITE_ID = :P49_SITE_ID',
'          AND FEE_COLLECTION_ID = (SELECT MAX(FEE_COLLECTION_ID) ',
'                                   FROM STUDENT_FEE_COLLECTION ',
'                                   WHERE STUDENT_ID = :P49_STUDENT_ID ',
'                                     AND SITE_ID = :P49_SITE_ID)',
'          ;',
'          EXCEPTION WHEN NO_DATA_FOUND THEN',
'             :P49_OPENING_BALANCE:=0;',
'      END;',
'      :P49_OPENING_BALANCE:= NVL(V_CL_BAL,0) + NVL(V_PRV_FEE,0) ;',
'  END;    ',
'ELSE',
'  BEGIN',
'      SELECT OPENING_BALANCE ',
'      INTO :P49_OPENING_BALANCE',
'        FROM STUDENT_FEE_COLLECTION',
'        WHERE STUDENT_ID = :P49_STUDENT_ID ',
'          AND SITE_ID = :P49_SITE_ID',
'          AND FEE_COLLECTION_ID = (SELECT MAX(FEE_COLLECTION_ID) ',
'                                   FROM STUDENT_FEE_COLLECTION ',
'                                   WHERE STUDENT_ID = :P49_STUDENT_ID ',
'                                     AND SITE_ID = :P49_SITE_ID)',
'              ;',
'          EXCEPTION WHEN NO_DATA_FOUND THEN',
'             :P49_OPENING_BALANCE:=0;     ',
'   END;          ',
' END IF;           '))
,p_attribute_02=>'P49_STUDENT_ID,P49_SITE_ID,P49_FEE_COLLECTION_ID'
,p_attribute_03=>'P49_OPENING_BALANCE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
