'    end LIST_CLASS,',
'     (substr("ASSESSMENT_ID", 1, 50)||( case when length("ASSESSMENT_ID") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("FIRST_NAME", 1, 50)||( case when length("FIRST_NAME") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "STUDENT_ASSESSMENT" x',
'where (:P50_SEARCH is null',
'        or upper(x."ASSESSMENT_ID") like ''%''||upper(:P50_SEARCH)||''%''',
'        or upper(x."FIRST_NAME") like ''%''||upper(:P50_SEARCH)||''%''',
'    )',
' AND SITE_ID=:APP_SITE_ID   ',
'order by ASSESSMENT_ID DESC'))
,p_ajax_enabled=>'Y'
