begin
wwv_flow_imp_page.create_page(
 p_id=>51
,p_name=>'Student Assessment'
,p_alias=>'STUDENT-ASSESSMENT'
,p_page_mode=>'MODAL'
,p_step_title=>'Student Assessment'
,p_autocomplete_on_off=>'OFF'
