wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(26841973536056530559)
,p_plug_name=>'Student Attendance'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ATTENDANCE_ID,',
'       ATTENDANCE_DATE,',
'       A.EMPLOYEE_ID,',
'       E.EMP_NAME||'' ''||E.LAST_NAME EMP_NAME,',
'       A.STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME STUDENT_NAME,',
'       A.SITE_ID,',
'       A.CLASS_ID,',
'       (SELECT C.CLASS_NAME FROM CLASSES C WHERE C.CLASS_ID=A.CLASS_ID)CLASS_NAME,',
'       (SELECT SB.SUBJECT_NAME FROM SUBJECTS SB WHERE SB.SUBJECT_ID=A.SUBJECT_ID)SUBJECT_NAME,',
'       (SELECT B.BOOK_NAME FROM BOOKS B WHERE B.BOOK_ID=A.BOOK_ID)BOOK_NAME,',
'       WEEKDAY,',
'       ATTENDANCE_STATUS,',
'       ATTENDANCE_TIME,',
'       REMARKS,',
'       A.FEED_BY,',
'       A.FEED_DATE,',
'       A.SUBJECT_ID,',
'       A.BOOK_ID,',
'       LP_ATT_STATUS',
'  from STUDENT_ATTENDANCE A,STUDENTS S,EMPLOYEES E',
'  WHERE A.STUDENT_ID=S.STUDENT_ID',
'    AND A.SITE_ID=S.SITE_ID',
'    AND A.EMPLOYEE_ID=E.EMP_ID',
'    AND A.SITE_ID =E.SITE_ID',
'    AND A.SITE_ID=:APP_SITE_ID',
'    AND UPPER(A.WEEKDAY)=UPPER(:P54_WEEKDAY)',
'    AND A.START_TIME=:P54_START_TIME',
'    AND A.END_TIME  =:P54_END_TIME ',
'    AND A.ATTENDANCE_DATE=:P54_DATE',
'   ',
'    '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P54_WEEKDAY,P54_START_TIME,P54_END_TIME,P54_DATE'
,p_prn_page_header=>'Student_Attendance'
);
