wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(27219057026759328201)
,p_event_id=>wwv_flow_imp.id(25649517883027496050)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_cNT NUMBER;',
'BEGIN',
'    SELECT COUNT(*) INTO V_CNT',
'       FROM STUDENT_ATTENDANCE SA',
'      WHERE /*NVL(SA.EMPLOYEE_ID,''O'')=NVL(:P54_EMPLOYEE_ID,''O'')',
'        AND*/ SA.SITE_ID    =:APP_SITE_ID',
'        AND UPPER(SA.WEEKDAY)=UPPER(:P54_WEEKDAY)',
'        AND SA.START_TIME    =:P54_START_TIME',
'        AND SA.END_TIME      =:P54_END_TIME',
'        AND ATTENDANCE_DATE  =:P54_DATE',
'       ;',
'IF V_CNT = 0 THEN',
'   INSERT INTO STUDENT_ATTENDANCE(ATTENDANCE_DATE,EMPLOYEE_ID,STUDENT_ID,SITE_ID,CLASS_ID,WEEKDAY,SUBJECT_ID,BOOK_ID,START_TIME,END_TIME,FEED_BY,FEED_DATE,LP_ATT_STATUS)',
'   select :P54_DATE,T.EMP_ID,T.STUDENT_ID,:APP_SITE_ID,T.CLASS_ID,CLS.WEEKDAY,S.SUBJECT_ID,S.BOOK_ID,:P54_START_TIME,:P54_END_TIME,:APP_USER,TRUNC(SYSDATE),''L''',
'     from TEACHER_ASSIGN_TO_STUDENT T,STUDENT_CLASSES_SCHEDULE S,CLASSES CS,CLASS_SCHEDULE CLS,BOOKS B,SUBJECTS SS,STUDENTS ST',
'    WHERE T.STUDENT_CLASS_SCHEDULE_ID= S.STUDENT_SCHEDULE_ID',
'      AND T.SITE_ID                  = S.SITE_ID',
'      AND T.CLASS_ID                 = CS.CLASS_ID',
'      AND S.CLASS_SHEDULE_ID         = CLS.SCHEDULE_ID',
'      AND S.SITE_ID                  = CLS.SITE_ID',
'      AND S.BOOK_ID                  = B.BOOK_ID(+)',
'      AND S.SUBJECT_ID               = SS.SUBJECT_ID',
'      AND T.STUDENT_ID               = ST.STUDENT_ID',
'      AND T.SITE_ID                  = ST.SITE_ID',
'      AND T.STATUS                   = ''A''',
'      AND CLS.STATUS                 = ''A''',
'      AND S.STATUS                   = ''A''',
'      AND ST.STATUS                  = ''A''',
'      --AND T.EMP_ID=NVL(:P54_EMPLOYEE_ID,T.EMP_ID)',
'      AND T.SITE_ID                  = :APP_SITE_ID',
'      AND UPPER(CLS.WEEKDAY)         = UPPER(:P54_WEEKDAY)',
'      AND CLS.START_TIME             = :P54_START_TIME',
'      AND CLS.END_TIME               = :P54_END_TIME',
'    UNION ALL',
'    SELECT :P54_DATE,SCR.EMPLOYEE_ID,SCR.STUDENT_ID,:APP_SITE_ID,SCR.CLASS_ID,SC.WEEKDAY,SCR.SUBJECT_ID,SCR.BOOK_ID,:P54_START_TIME,:P54_END_TIME,:APP_USER,TRUNC(SYSDATE),''M''',
'      FROM STUDENT_CLASS_RESCHEDULING SCR , CLASS_SCHEDULE SC,BOOKS B,SUBJECTS SS,STUDENTS S',
'     WHERE SCR.CLASS_SHEDULE_ID=SC.SCHEDULE_ID    ',
'       AND SCR.SITE_ID       =SC.SITE_ID',
'       AND SCR.BOOK_ID       =B.BOOK_ID(+)',
'       AND SCR.SUBJECT_ID    =SS.SUBJECT_ID',
'       AND SCR.STUDENT_ID    =S.STUDENT_ID',
'       AND SCR.SITE_ID       =S.SITE_ID',
'       AND SCR.STATUS        =''A''',
'       AND SC.STATUS         =''A''  ',
'       AND S.STATUS          =''A'' ',
'       AND SCR.EMPLOYEE_ID   =NVL(:P54_EMPLOYEE_ID,SCR.EMPLOYEE_ID)',
'       AND SCR.SITE_ID       =:APP_SITE_ID',
'       AND UPPER(SC.WEEKDAY) =UPPER(:P54_WEEKDAY)    ',
'       AND SC.START_TIME     =:P54_START_TIME',
'       AND SC.END_TIME       =:P54_END_TIME',
'       ;',
'   END IF;    ',
'END;',
''))
,p_attribute_02=>'P54_WEEKDAY,P54_START_TIME,P54_END_TIME,P54_DATE'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
