begin
wwv_flow_imp_page.create_page(
 p_id=>58
,p_name=>'Student lesson reshedule'
,p_alias=>'STUDENT-LESSON-RESHEDULE'
,p_step_title=>'Missing Lesson Plan'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'body {',
'    font-family: ''Arial'', sans-serif;',
'}',
'',
'input {',
'    height: 45px; ',
'    line-height: 45px; ',
'    padding: 8px;  ',
'    border-radius: 5px;',
'    border: 1px solid #ccc; ',
'}',
'.a-MediaBlock-graphic,.a-IRR-reportSummary-item--controlBreak {',
'    display: none !important;',
'}',
'.a-IG-reportSummary-item--controlBreak, .a-IG-controls-item--controlBreak, .a-IRR-reportSummary-item--controlBreak, .a-IRR-controls-item--controlBreak {',
'    display: none !important;',
'}',
'#R27676075134069326729_actions_menu_10{',
'    display: none !important;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(27676075134069326729)
,p_plug_name=>'Missing Lesson Plan'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>70
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       SCR.EMPLOYEE_ID,',
'       E.EMP_NAME||'' ''||E.LAST_NAME EMP_NAME,',
'       S.STAGE||''-''||S.STUDENT_ID STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME STUDENT_NAME,',
'       C.CLASS_NAME,',
'       SB.SUBJECT_NAME,',
'       B.BOOK_NAME,',
'       CS.WEEKDAY,',
'       CS.START_TIME,',
'       CS.END_TIME,',
'       SCR.RESHEDULE_DATE',
'  from STUDENT_CLASS_RESCHEDULING SCR,STUDENTS S,CLASSES C,CLASS_SCHEDULE CS,SUBJECTS SB,BOOKS B,EMPLOYEES E',
'  WHERE SCR.STUDENT_ID    = S.STUDENT_ID',
'    AND SCR.SITE_ID       = S.SITE_ID',
'    AND SCR.CLASS_ID      = C.CLASS_ID',
'    AND SCR.CLASS_SHEDULE_ID=CS.SCHEDULE_ID',
'    AND SCR.SITE_ID        = CS.SITE_ID',
'    AND SCR.SUBJECT_ID     = SB.SUBJECT_ID',
'    AND SCR.BOOK_ID        = B.BOOK_ID(+)',
'    AND SCR.EMPLOYEE_ID    = E.EMP_ID(+)',
'    AND SCR.SITE_ID        = :APP_SITE_ID',
'    AND SCR.EMPLOYEE_ID    = NVL(:P58_EMPLOYEE_ID,SCR.EMPLOYEE_ID)    ',
'    AND SCR.STUDENT_ID     = NVL(:P58_STUDENT_ID,SCR.STUDENT_ID)   ',
'    AND SCR.SUBJECT_ID     = NVL(:P58_SUBJECT,SCR.SUBJECT_ID)',
'    AND NVL(SCR.BOOK_ID,0) = NVL(:P58_BOOK,NVL(SCR.BOOK_ID,0))',
'    AND UPPER(CS.WEEKDAY)  = NVL(UPPER(:P58_WEEKDAY),UPPER(CS.WEEKDAY))',
'    AND SCR.STATUS         = ''A''',
'    AND CS.STATUS          = ''A''',
'    AND S.STATUS           = ''A'' ',
'    ORDER BY  CASE',
'            WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'            WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'            WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'          END,LENGTH(STUDENT_ID),STUDENT_ID'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P58_EMPLOYEE_ID,P58_STUDENT_ID,P58_SUBJECT,P58_BOOK,P58_WEEKDAY,P58_BRANCHES'
,p_prn_page_header=>'Student lesson reshedule'
);
