 p_id=>wwv_flow_imp.id(29828991596829352588)
,p_plug_name=>'Student Attendance'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM (',
'  SELECT ',
'    S.STAGE||''-''||S.STUDENT_ID STUDENT_ID,',
'    S.STUDENT_NAME || '' '' || S.LAST_NAME AS STUDENT_NAME,',
'    TO_CHAR(ATT.ATTENDANCE_DATE, ''DD'') AS DAY,',
'    ATT.ATTENDANCE_STATUS AS ATTENDANCE_STATUS',
'  FROM STUDENTS S',
'',
'  LEFT JOIN STUDENT_ATTENDANCE ATT',
'    ON ATT.STUDENT_ID = S.STUDENT_ID',
'    AND ATT.SITE_ID = S.SITE_ID',
'    AND TO_CHAR(ATT.ATTENDANCE_DATE, ''MM-YYYY'') = NVL(:P61_MONTH, TO_CHAR(SYSDATE, ''MM-YYYY''))',
'',
'  WHERE (:P61_ADMISSION_NO IS NULL OR (S.STUDENT_ID = NVL(:P61_ADMISSION_NO,S.STUDENT_ID)))',
'    AND S.SITE_ID = :APP_SITE_ID--:P61_BRANCHES',
'    AND (:P61_ATTENDANCE_STATUS IS NULL OR (ATT.ATTENDANCE_STATUS = NVL(:P61_ATTENDANCE_STATUS,ATT.ATTENDANCE_STATUS)))',
')',
'PIVOT (',
'  MAX(ATTENDANCE_STATUS)',
'  FOR DAY IN (',
'    ''01'' AS "01", ''02'' AS "02", ''03'' AS "03", ''04'' AS "04", ''05'' AS "05",',
'    ''06'' AS "06", ''07'' AS "07", ''08'' AS "08", ''09'' AS "09", ''10'' AS "10",',
'    ''11'' AS "11", ''12'' AS "12", ''13'' AS "13", ''14'' AS "14", ''15'' AS "15",',
'    ''16'' AS "16", ''17'' AS "17", ''18'' AS "18", ''19'' AS "19", ''20'' AS "20",',
'    ''21'' AS "21", ''22'' AS "22", ''23'' AS "23", ''24'' AS "24", ''25'' AS "25",',
'    ''26'' AS "26", ''27'' AS "27", ''28'' AS "28", ''29'' AS "29", ''30'' AS "30",',
'    ''31'' AS "31"',
'  )',
')',
'order by CASE',
'            WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'            WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'            WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'          END,LENGTH(STUDENT_ID),STUDENT_ID',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P61_ADMISSION_NO,P61_ATTENDANCE_STATUS,P61_MONTH'
