,p_plug_name=>'Fee Reminder Report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select REMINDER_ID,',
'       S.STAGE||''-''||F.STUDENT_ID STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME STUDENT_NAME,',
'       F.SITE_ID,',
'        REMINDER_COUNT,',
'       REMINDER_COMMENT,',
'       REMINDER_DATE,',
'       F.SUSPENDED,',
'       F.COMMENTS_IF_ANY,',
'       F.FEED_BY,',
'       F.FEED_DATE',
'  from FEE_REMINDER F,STUDENTS S',
'  WHERE F.STUDENT_ID=S.STUDENT_ID',
'    AND F.SITE_ID=S.SITE_ID',
'    AND F.SITE_ID=:APP_SITE_ID--:P70_BRANCHES',
'    AND F.STUDENT_ID = NVL(:P70_ADMISSION_NO,F.STUDENT_ID)',
'    AND TO_CHAR(F.REMINDER_DATE,''DD-MON-YYYY'') = NVL(:P70_REMINDER_DATE,TO_CHAR(F.REMINDER_DATE,''DD-MON-YYYY''))',
'    AND (UPPER(:P70_REMINDER)    IS NULL OR (UPPER(F.REMINDER_COMMENT) = UPPER(:P70_REMINDER)))',
'    AND (UPPER(:P70_COMMENTS_IF_ANY) IS NULL OR (UPPER(F.COMMENTS_IF_ANY)  = UPPER(:P70_COMMENTS_IF_ANY)))',
'    AND (UPPER(:P70_SUSPENSION)  IS NULL OR (UPPER(F.SUSPENDED)        = UPPER(:P70_SUSPENSION)))',
'    order by REMINDER_ID desc',
''))
