 p_id=>wwv_flow_imp.id(97090834964979081901)
,p_name=>'Lesson Plan Schedule'
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select STUDENT_SCHEDULE_ID,',
'       S.STUDENT_ID,',
'       STU.STUDENT_NAME,',
'       S.CLASS_ID,',
'       CS.CLASS_NAME,',
'       CL.CLASS_NAME AS STUDENT_YEAR,',
'       S.SUBJECT_ID,',
'       SB.SUBJECT_NAME,',
'       S.BOOK_ID,',
'       B.BOOK_NAME,',
'       C.WEEKDAY,',
'       C.START_TIME,',
'       C.END_TIME,',
'       CLASS_SHEDULE_ID,',
'       DECODE(S.STATUS,''A'',''Active'',''I'',''Inactive'')STATUS,',
'       S.FEED_BY,',
'       S.FEED_DATE,',
'       S.SITE_ID',
'  from STUDENT_CLASSES_SCHEDULE S,CLASS_SCHEDULE C,SUBJECTS SB,BOOKS B,CLASSES CS, CLASSES CL,STUDENTS STU',
' where S.CLASS_SHEDULE_ID=C.SCHEDULE_ID',
'   AND S.STUDENT_ID     = STU.STUDENT_ID',
'   AND S.SITE_ID        = STU.SITE_ID',
'   AND S.SITE_ID        = C.SITE_ID',
'   AND S.SUBJECT_ID     = SB.SUBJECT_ID',
'   AND S.BOOK_ID        = B.BOOK_ID(+)',
'   AND S.CLASS_ID       =CS.CLASS_ID',
'   AND STU.CLASS_ID     = CL.CLASS_ID',
'   --AND S.STATUS=''A''',
'   AND S.STUDENT_ID  = NVL(:P73_STUDENT_ID,S.STUDENT_ID)',
'   AND S.CLASS_ID    = NVL(:P73_CLASS_ID,S.CLASS_ID)',
'   AND S.SUBJECT_ID  = NVL(:P73_SUBJECT_ID,S.SUBJECT_ID)',
'   AND NVL(S.BOOK_ID,''0'') = NVL(:P73_BOOK_ID,NVL(S.BOOK_ID,0))',
'   AND C.WEEKDAY     = NVL(:P73_WEEKDAY,C.WEEKDAY)',
'   AND S.SITE_ID     = :APP_SITE_ID',
'   ORDER BY STUDENT_SCHEDULE_ID, TO_DATE(C.START_TIME, ''HH24:MI'') ASC'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P73_STUDENT_ID,P73_CLASS_ID,P73_SUBJECT_ID,P73_BOOK_ID,P73_WEEKDAY'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_prn_output=>'N'
