wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(61266495716718893013)
,p_name=>'Student Fee Detail'
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       S.STAGE||''-''||SFC.STUDENT_ID STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME STUDENT_NAME,',
'       C.CLASS_NAME,',
'       SITE_NAME,',
'       TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'')FEE_MONTH,',
'       ''Payment''||'' ''||PAYMENT_COUNT PAYMENT_COUNT,',
'       OPENING_BALANCE,',
'      (CASE ',
'       WHEN ROW_NUMBER() OVER (PARTITION BY SFC.STUDENT_ID, SFC.SITE_ID,SFC.FEE_MONTH, SFC.MONTHLY_FEE ORDER BY FEE_COLLECTION_ID) = 1 ',
'       THEN MONTHLY_FEE ',
'       ELSE 0 ',
'       END) AS MONTHLY_FEE,',
'       REGISTRATION_FEE ADMISSION_FEE,',
'       DISCOUNT,',
'       BOOKS_FEE,',
'       EXAM_FEE,',
'       PAST_PAPER_FEE,',
'       /*(CASE WHEN ABS(OPENING_BALANCE) >= MONTHLY_FEE THEN MONTHLY_FEE ',
'       ELSE(NVL((CASE ',
'                 WHEN ROW_NUMBER() OVER (PARTITION BY SFC.STUDENT_ID, SFC.SITE_ID,SFC.FEE_MONTH, SFC.MONTHLY_FEE ORDER BY FEE_COLLECTION_ID) = 1 ',
'                 THEN MONTHLY_FEE ',
'                 ELSE 0 ',
'            END),0) + NVL(OPENING_BALANCE,0)+NVL(REGISTRATION_FEE,0) + NVL(DISCOUNT,0) + NVL(EXAM_FEE,0)+ NVL(BOOKS_FEE,0)  + NVL(PAST_PAPER_FEE,0) ',
'        )END)  AS TOTAL_FEE,*/',
'        NVL((CASE ',
'                 WHEN ROW_NUMBER() OVER (PARTITION BY SFC.STUDENT_ID, SFC.SITE_ID,SFC.FEE_MONTH, SFC.MONTHLY_FEE ORDER BY FEE_COLLECTION_ID) = 1 ',
'                 THEN MONTHLY_FEE ',
'                 ELSE 0 ',
'            END),0) + NVL(OPENING_BALANCE,0)+NVL(REGISTRATION_FEE,0) + NVL(DISCOUNT,0) + NVL(EXAM_FEE,0)+ NVL(BOOKS_FEE,0)  + NVL(PAST_PAPER_FEE,0) ',
'        AS TOTAL_FEE,',
'       RECEIVED_AMOUNT,',
'       CLOSING_BALANCE,',
'       CASE WHEN P.PAYMENT_NAME=''Adjustment'' THEN NULL ELSE P.PAYMENT_NAME END AS PAYMENT_NAME,',
'       TO_CHAR(PAYMENT_DATE,''DD-MON-YYYY'')PAYMENT_DATE,',
'       SFC.COMMENTS,',
'       SFC.STATUS,',
'       SFC.FEED_BY,',
'       TO_CHAR(SFC.FEED_DATE,''DD-MON-YYYY'')FEED_DATE',
'  from STUDENT_FEE_COLLECTION SFC,STUDENTS S,CLASSES C,SITES ST,PAYMENT_TYPE P',
' where SFC.STUDENT_ID=S.STUDENT_ID',
'   AND SFC.SITE_ID=S.SITE_ID',
'   AND S.CLASS_ID=C.CLASS_ID',
'   AND SFC.SITE_ID=ST.SITE_ID',
'   AND SFC.PAYMENT_METHOD=P.PAY_ID',
'   --AND SFC.FEE_MONTH=TO_CHAR(SYSDATE,''MM-YYYY'')',
'   AND S.CLASS_ID=NVL(:P77_CLASS_ID,S.CLASS_ID)',
'   AND SFC.STUDENT_ID=NVL(:P77_STUDENT_ID,SFC.STUDENT_ID)',
'   AND TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') =NVL(TO_CHAR(TO_DATE(:P77_FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') ,TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY''))',
'   AND SFC.SITE_ID=:APP_SITE_ID--P77_BRANCHES',
' order by STUDENT_ID,FEE_COLLECTION_ID,PAYMENT_COUNT '))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P77_STUDENT_ID,P77_FEE_MONTH,P77_BRANCHES'
,p_lazy_loading=>true
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_break_type_flag=>'REPEAT_HEADINGS_ON_BREAK_1'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_prn_format=>'PDF'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
