'select "SP_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P79_SP_ID'', p_values => "SP_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P79_SP_ID,''0'') = "SP_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    SP_ID||'' , ''||',
'    (substr("STUDENT_ID", 1, 50)||( case when length("STUDENT_ID") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'   (substr(TO_CHAR(SP_DATE,''DD-MON-YYYY''), 1, 50)||( case when length("SP_DATE") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "STUDENT_PROGRESS" x',
'where (:P79_SEARCH is null',
'        or upper(x."STUDENT_ID") like ''%''||upper(:P79_SEARCH)||''%''',
'        or upper(x."SP_DATE") like ''%''||upper(:P79_SEARCH)||''%''',
'    )',
' AND SITE_ID=:APP_SITE_ID   ',
' AND PROGRESS_TYPE = ''M''',
'order by "SP_ID" desc',
''))
