,p_name=>'Catchup Lesson Plan Inactive'
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select SCR.ROWID,',
'       SCR.RESCHEDULING_ID,',
'       SCR.RESHEDULE_DATE,',
'       SCR.EMPLOYEE_ID,',
'       E.EMP_NAME||'' ''||E.LAST_NAME EMP_NAME,',
'       S.STAGE||''-''||SCR.STUDENT_ID STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME STUDENT_NAME,',
'       SCR.CLASS_ID,',
'       C.CLASS_NAME,',
'       SCR.SUBJECT_ID,',
'       SB.SUBJECT_NAME,',
'       SCR.BOOK_ID,',
'       B.BOOK_NAME,',
'       CLASS_SHEDULE_ID,',
'       CS.WEEKDAY,',
'       CS.START_TIME,',
'       CS.END_TIME,',
'       SCR.SITE_ID,',
'       SCR.STATUS',
'  from STUDENT_CLASS_RESCHEDULING SCR,STUDENTS S,CLASSES C,CLASS_SCHEDULE CS,SUBJECTS SB,BOOKS B,EMPLOYEES E',
'  WHERE SCR.STUDENT_ID      = S.STUDENT_ID',
'    AND SCR.SITE_ID         = S.SITE_ID',
'    AND SCR.CLASS_ID        = C.CLASS_ID',
'    AND SCR.CLASS_SHEDULE_ID= CS.SCHEDULE_ID',
'    AND SCR.SITE_ID         = CS.SITE_ID',
'    AND SCR.SUBJECT_ID      = SB.SUBJECT_ID',
'    AND SCR.BOOK_ID         = B.BOOK_ID(+)',
'    AND SCR.EMPLOYEE_ID     = E.EMP_ID(+)',
'    AND SCR.SITE_ID         = :APP_SITE_ID',
'    AND SCR.EMPLOYEE_ID     = NVL(:P81_EMPLOYEE_ID,SCR.EMPLOYEE_ID)    ',
'    AND SCR.STUDENT_ID      = NVL(:P81_STUDENT_ID,SCR.STUDENT_ID)   ',
'    AND SCR.SUBJECT_ID      = NVL(:P81_SUBJECT,SCR.SUBJECT_ID)',
'    AND NVL(SCR.BOOK_ID,0)  = NVL(:P81_BOOK,NVL(SCR.BOOK_ID,0))',
'    AND UPPER(CS.WEEKDAY)   = NVL(UPPER(:P81_WEEKDAY),UPPER(CS.WEEKDAY))',
'    AND SCR.STATUS          = ''I''',
'    AND CS.STATUS           = ''A''',
'    AND S.STATUS            = ''A''',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P81_EMPLOYEE_ID,P81_STUDENT_ID,P81_SUBJECT,P81_BOOK,P81_WEEKDAY'
