'   INTO V_PERM',
'   FROM ROLE_PERMISSIONS RP',
'   WHERE RP.ROLE_ID IN (',
'                       SELECT ROLE_ID',
'                         FROM ASSIGN_ROLE_USER',
'                        WHERE APP_USER = :APP_USER',
'                        )',
'   AND RP.PERMISSION_ID IN (60,94);',
