);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(43989642403516139001)
,p_plug_name=>'Parents Contract'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>20
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="parents_contract" style="max-width: 800px; margin: auto; font-family: Arial, sans-serif;">',
'',
'  <h2 style="text-align: center; margin-bottom: 30px;">Parent Contract</h2>',
'  <!-- Logo on the left -->',
'  <img src="#APP_FILES#fine_tutor-removebg-preview.png" alt="Logo" style="float: right; height: 50px; margin-left: 20px; margin-top: -50px; margin-bottom: 10px">',
'  <!-- Top Info Table -->',
'<table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; border: 1px solid #000; text-align: left;">',
'  <tr>',
'    <th style="border: 1px solid #000; padding: 10px;">Ad. No.</th>',
'    <th style="border: 1px solid #000; padding: 10px;">Student Name</th>',
'    <th style="border: 1px solid #000; padding: 10px;">Year</th>',
'  </tr>',
'  <tr>',
'    <td style="border: 1px solid #000; padding: 10px; height: 25px;" id="show_id"></td>',
'    <td style="border: 1px solid #000; padding: 10px; height: 25px;" id="show_name"></td>',
'    <td style="border: 1px solid #000; padding: 10px; height: 25px;" id="show_class"></td>',
'  </tr>',
'</table>',
'',
'<!-- Terms and Conditions Header Box -->',
'<div style="background-color: #e0e0e0; padding: 6px 20px; border: 1px solid #000; border-bottom: none; font-weight: bold; font-size: 14px; text-align: center; height:30px">',
'  Terms and Conditions',
'</div>',
'  <!-- Box 1: Parents -->',
'  <div style="border: 1px solid #000; padding: 20px; margin-bottom: 0; font-size: 14px;">',
unistr('    <h3 style="margin-top: 0; margin-bottom: 10px;">Parents \2013 I agree to:</h3>'),
'    <ol style="margin-top: 0; margin-bottom: 0;">',
unistr('      <li>Attendance and punctuality are important for your child\2019s progress. Children must come on time for lessons.</li>'),
'      <li>If your child has been absent, they will have up to 30 days from the day of absent to book in a catch-up session.</li>',
'      <li>If you have informed us about their absence prior to the lesson starting, your child will be entitled to catch up session.</li>',
'      <li>Inform about any changes to lesson plan before the 25th of the month so that it can be changed for the following month.</li>',
unistr('      <li>Give 4 weeks\2019 notice required upon pausing or ending lessons.</li>'),
'      <li>Support my child at home with their learning and make sure homework is completed.</li>',
'    </ol>',
'  </div>',
'',
'  <!-- Box 2: Pupil -->',
'  <div style="border-left: 1px solid #000; border-right: 1px solid #000; border-bottom: 1px solid #000; padding: 20px; margin-top: -1px; margin-bottom: 0; font-size: 14px;">',
unistr('    <h3 style="margin-top: 0; margin-bottom: 10px;">Pupil \2013 I agree to:</h3>'),
'    <ol style="margin-top: 0; margin-bottom: 0;">',
'      <li>I will always come in for all my lessons and be on time at the beginning of the day, after lunch and breaks.</li>',
'      <li>Come prepared with my books, stationery, notebooks and completed homework.</li>',
'      <li>Treat others how you want to be treated, with kindness. Be respectful towards my classmates, teachers, and belongings.</li>',
'      <li>I will listen to my teachers and wait for my turn when speaking.</li>',
'      <li>Have a good attitude and positive behaviour when I come into class.</li>',
'      <li>Use the bathroom before lesson starts and only allowed to use the bathroom once during the lesson (unless you have provided medical note).</li>',
'      <li>Do not eat or drink in class (except for water).</li>',
'      <li>Come prepared with my snacks and will not leave my classroom during break times.</li>',
'      <li>No phones allowed during lesson.</li>',
'    </ol>',
'    <p style="margin-top: 15px;"><strong>If the following terms have not been met:</strong></p>',
'    <ul style="margin-top: 0; margin-left: 20px;">',
unistr('      <li>First warning \2013 Parents are informed, and pupil sent home.</li>'),
unistr('      <li>Second warning \2013 Lessons will be suspended for one week and parents called in for a meeting.</li>'),
unistr('      <li>Final decision \2013 Pupil will be suspended.</li>'),
'    </ul>',
'  </div>',
'',
'  <!-- Box 3: Tutors -->',
'  <div style="border: 1px solid #000; border-top: none; padding: 20px; margin-top: -1px; margin-bottom: 30px; font-size: 14px;">',
unistr('    <h3 style="margin-top: 0; margin-bottom: 10px;">Fine Tutors \2013 I agree to:</h3>'),
'    <ol style="margin-top: 0; margin-bottom: 0;">',
'      <li>Create a safe and welcoming environment.</li>',
'      <li>Provide excellent learning support for all pupils.</li>',
unistr('      <li>Provide regular update on pupil progress with parents. You are welcome to arrange face to face appointment for updates on your child\2019s progress at any point in the year.</li>'),
'    </ol>',
'  </div>',
'',
'  <p>',
'    <strong>Parent Signature:</strong>',
'    <span  id="parents_name" style="border-bottom: 1px solid #000; padding: 0 100px;">&nbsp;</span> &nbsp;&nbsp;&nbsp;',
'    <strong>Date:</strong>',
'    <span id="dates" style="border-bottom: 1px solid #000; padding: 0 60px;"></span>',
'  </p>',
'  <p>',
'    <strong>Staff Signature:</strong>',
'    <span id="feed_name" style="border-bottom: 1px solid #000; padding: 0 100px;">&nbsp;</span> &nbsp;&nbsp;&nbsp;',
'    <strong>Date:</strong>',
'    <span id="dates1" style="border-bottom: 1px solid #000; padding: 0 60px;"></span>',
'  </p>',
'',
'</div>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
