wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(43989647325874139050)
,p_plug_name=>'Parent Signature'
,p_region_name=>'parent_signature'
,p_parent_plug_id=>wwv_flow_imp.id(43989642520086139002)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- Signature Canvas -->',
'<canvas id="signature-pad" width="600" height="200" style="border:1px solid #000;"></canvas>',
'',
'<!-- Signature Pad Library -->',
'<script src="https://cdn.jsdelivr.net/npm/signature_pad@5.0.7/dist/signature_pad.umd.min.js"></script>',
'',
'<script>',
'  // Wait for DOM to fully load',
'  document.addEventListener("DOMContentLoaded", function() {',
'    // Get canvas element',
'    var canvas = document.getElementById("signature-pad");',
'    ',
'    // Resize the canvas for Retina displays (high-DPI screens)',
'    function resizeCanvas() {',
'      var ratio = Math.max(window.devicePixelRatio || 1, 1);',
'      canvas.width = canvas.offsetWidth * ratio;',
'      canvas.height = canvas.offsetHeight * ratio;',
'      canvas.getContext("2d").scale(ratio, ratio);',
'    }',
'    ',
'    // Call resizeCanvas to adjust canvas size immediately',
'    resizeCanvas();',
'    window.addEventListener("resize", resizeCanvas);  // Re-size if window is resized',
'    ',
'    // Initialize SignaturePad',
'    var signaturePad = new SignaturePad(canvas);',
'  document.getElementById("clear").addEventListener("click", function () {',
'      signaturePad.clear();',
'    });',
'    // Save button functionality',
'  document.getElementById("generate_contract").addEventListener("click", function () {',
'',
'    // Get base64 signature image',
'    const dataURL = signaturePad.toDataURL("image/png");',
'',
'    const con_id = document.getElementById("P82_CONTRACT_ID").value;',
'',
'    // Create image element and insert into contract',
'    ',
'    if (con_id){',
'        var imgSrc = document.getElementById("P82_SIGNATURE");',
'          if (imgSrc && imgSrc.src){',
'            const signatureImg = document.createElement("img");',
'            signatureImg.src = imgSrc.src;',
'            signatureImg.style.height = "50px";  // adjust size as needed',
'            signatureImg.style.verticalAlign = "middle";',
'',
'            const parentSignatureSpan = document.getElementById("parents_name");',
'            parentSignatureSpan.innerHTML = ""; // clear existing content',
'            parentSignatureSpan.appendChild(signatureImg);',
'',
'          }else{',
'             apex.item("P82_SIGNATURE_DATA").setValue(dataURL);',
'            const signatureImg = document.createElement("img");',
'            signatureImg.src = dataURL;',
'            signatureImg.style.height = "50px";  // adjust size as needed',
'            signatureImg.style.verticalAlign = "middle";',
'',
'            const parentSignatureSpan = document.getElementById("parents_name");',
'            parentSignatureSpan.innerHTML = ""; // clear existing content',
'            parentSignatureSpan.appendChild(signatureImg);',
'          }',
'         ',
'          ',
'',
'    }else{',
'               // Set base64 to hidden field',
'         apex.item("P82_SIGNATURE_DATA").setValue(dataURL);',
'',
'        const signatureImg = document.createElement("img");',
'        signatureImg.src = dataURL;',
'        signatureImg.style.height = "50px";  // adjust size as needed',
'        signatureImg.style.verticalAlign = "middle";',
'',
'        const parentSignatureSpan = document.getElementById("parents_name");',
'        parentSignatureSpan.innerHTML = ""; // clear existing content',
'        parentSignatureSpan.appendChild(signatureImg);',
'    }  ',
'',
'    // Set today''s date',
'    const today = new Date().toLocaleDateString();',
'    document.getElementById("dates").textContent = today;',
'  });',
'});',
'</script>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
