 p_id=>wwv_flow_imp.id(45517020340233944110)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'insert parent contract_1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_blob       BLOB;',
'  l_base64     CLOB := :P82_SIGNATURE_DATA;',
'  l_mime_type  VARCHAR2(100);',
'  l_file_ext   VARCHAR2(10);',
'  v_cont_id    NUMBER;',
'BEGIN',
'  -- Extract MIME type from base64 prefix',
'  IF INSTR(l_base64, ''data:'') > 0 AND INSTR(l_base64, '';base64,'') > 0 THEN',
'      -- Strip off the prefix "data:image/png;base64,"',
'    l_base64 := SUBSTR(l_base64, INSTR(l_base64, ''base64,'') + 7);',
'  END IF;',
'',
'  -- Convert base64 CLOB to BLOB',
'  l_blob := APEX_WEB_SERVICE.CLOBBASE642BLOB(l_base64);',
'',
'  -- Insert basic contract data first',
'  INSERT INTO PARENTS_CONTRACT (',
'    STUDENT_ID, CLASS_ID, SITE_ID, FEED_BY, FEED_DATE, STATUS, PARENT_NAME',
'  ) VALUES (',
'    :P82_STUDENT_ID, :P82_CLASS, :APP_SITE_ID, :APP_USER, TRUNC(SYSDATE), ''Y'', :P82_PARENTS_NAME',
'  );',
'',
'  -- Get generated CONTRACT_ID',
'  SELECT MAX(CONTRACT_ID)',
'    INTO v_cont_id',
'    FROM PARENTS_CONTRACT;',
'',
'  -- Update with BLOB and MIME info',
'  UPDATE PARENTS_CONTRACT',
'     SET SIGNATURE   = l_blob',
'   WHERE CONTRACT_ID = v_cont_id;',
'',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>45517020340233944110
);
