,p_name=>'Get Hours Fee'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_HOURLY_FEE NUMBER;',
'BEGIN  ',
'  BEGIN',
'    SELECT TUITION_FEE INTO V_HOURLY_FEE',
'      FROM FEE_SCHEDULE F           ',
'     WHERE F.CLASS_ID         = :CLASS_ID',
'       AND F.TUITION_FEE_TYPE = :TUITION_FEE_TYPE',
'       AND F.TUTION_TIME      = :TUTION_TIME',
'       AND F.STUDENT_TYPE     = :STUDENT_TYPE',
'       AND F.SITE_ID          = :APP_SITE_ID',
'       AND STATUS             = ''A''',
'       ; ',
'    EXCEPTION WHEN NO_DATA_FOUND THEN',
'       V_HOURLY_FEE:=0;   ',
'  END ;     ',
'   --RAISE_APPLICATION_ERROR(-20001,V_HOURLY_FEE);',
'   :TUITION_FEE := V_HOURLY_FEE - ((V_HOURLY_FEE / 100) * NVL(:HOURLY_FEE_DISC,0));',
'END;'))
,p_attribute_02=>'CLASS_ID,TUITION_FEE_TYPE,TUTION_TIME,STUDENT_TYPE'
,p_attribute_03=>'TUITION_FEE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
