'select FEE_ID,',
'       FEE_MONTH,',
'       SITE_ID,',
'       PAYMENT_COUNT,',
'       PARENT_NAME,',
'       STUDENT_IDS,',
'       OPENING_BALANCE,',
'       CASE  WHEN PAYMENT_COUNT = 1 THEN ',
'                  MONTHLY_FEE',
'              ELSE',
'                 0',
'              END AS MONTHLY_FEE,      ',
'       ADJUSTMENT,',
'       CASE WHEN PAYMENT_COUNT = 1 THEN',
'                 (NVL(OPENING_BALANCE,0)+NVL(MONTHLY_FEE,0)+NVL(ADJUSTMENT,0))',
'            ELSE',
'                  (NVL(OPENING_BALANCE,0)+NVL(ADJUSTMENT,0)) ',
'            END AS PAYABLE,      ',
'       RECEIVED_AMOUNT,',
'       CLOSING_BALANCE,',
'       PAYMENT_METHOD,',
'       PAYMENT_DATE,',
'       COMMENTS,',
