wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(90348517075434361207)
,p_name=>'Get OPN Balanace'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P99_PARENT_NAME'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(90348517102228361208)
,p_event_id=>wwv_flow_imp.id(90348517075434361207)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P99_FEE_ID IS NULL THEN',
'DECLARE',
'   V_PRV_FEE NUMBER;',
'    V_CL_BAL NUMBER;',
'  BEGIN     ',
'      BEGIN',
'        SELECT CLOSING_BALANCE INTO V_CL_BAL',
'        FROM PWS_FEES',
'        WHERE UPPER(PARENT_NAME) = UPPER(:P99_PARENT_NAME) ',
'          AND SITE_ID = :APP_SITE_ID',
'          AND FEE_ID = (SELECT MAX(FEE_ID) ',
'                           FROM PWS_FEES ',
'                           WHERE UPPER(PARENT_NAME) = UPPER(:P99_PARENT_NAME)',
'                             AND SITE_ID = :APP_SITE_ID)',
'          ;',
'          EXCEPTION WHEN NO_DATA_FOUND THEN',
'             :P99_OPENING_BALANCE:=0;',
'      END;',
'      --raise_application_error(-20001,V_CL_BAL);',
'      :P99_OPENING_BALANCE:= NVL(V_CL_BAL,0) + NVL(V_PRV_FEE,0) ;',
'  END;    ',
'ELSE',
'  BEGIN',
'      SELECT OPENING_BALANCE ',
'        INTO :P99_OPENING_BALANCE',
'        FROM PWS_FEES',
'        WHERE UPPER(PARENT_NAME) = UPPER(:P99_PARENT_NAME)',
'          AND SITE_ID = :APP_SITE_ID',
'          AND FEE_ID = (SELECT MAX(FEE_ID) ',
'                           FROM PWS_FEES ',
'                           WHERE UPPER(PARENT_NAME) = UPPER(:P99_PARENT_NAME) ',
'                             AND SITE_ID = :APP_SITE_ID)',
'              ;',
'          EXCEPTION WHEN NO_DATA_FOUND THEN',
'             :P99_OPENING_BALANCE:=0;     ',
'   END;          ',
' END IF;           '))
,p_attribute_02=>'P99_STUDENT_IDS,P99_FEE_ID,P99_PARENT_NAME'
,p_attribute_03=>'P99_OPENING_BALANCE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
