,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LISTAGG(S.STUDENT_ID, '','') WITHIN GROUP (ORDER BY S.STUDENT_ID),ROUND(SUM(TOTAL_FEE)) INTO :P99_STUDENT_IDS,:P99_MONTHLY_FEE',
'  FROM STUDENTS S,STUDENT_PARENTS P,STUDENT_FEES F',
' WHERE S.STUDENT_ID         = P.STUDENT_ID',
'   AND S.SITE_ID            = P.SITE_ID',
'   AND S.STUDENT_ID         = F.STUDENT_ID(+)',
'   AND S.SITE_ID            = F.SITE_ID(+)',
'   AND UPPER(P.PARENT_NAME) = UPPER(:P99_PARENT_NAME)',
'   AND S.SITE_ID            = :APP_SITE_ID',
'   ;'))
,p_attribute_02=>'P99_PARENT_NAME'
,p_attribute_03=>'P99_STUDENT_IDS,P99_MONTHLY_FEE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
