,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_PAY_COOUNT NUMBER;',
'BEGIN  ',
'  BEGIN',
'      SELECT NVL(MAX(PAYMENT_COUNT),0)+1 INTO V_PAY_COOUNT',
'        FROM PWS_FEES C   ',
'       WHERE C.STUDENT_IDS IN (:P99_STUDENT_IDS)',
'         AND C.SITE_ID    = :APP_SITE_ID',
'         AND C.FEE_MONTH  = :P99_FEE_MONTH  ',
'         ;',
'     EXCEPTION WHEN NO_DATA_FOUND THEN',
'         V_PAY_COOUNT:=1;',
'     END',
'     ;      ',
' IF V_PAY_COOUNT = 1 THEN',
'       :P99_PAYABLE:=NVL(:P99_MONTHLY_FEE,0)+NVL(:P99_OPENING_BALANCE,0)+NVL(:P99_ADJUSTMENT,0);',
'    ELSE ',
'       :P99_PAYABLE:=NVL(:P99_OPENING_BALANCE,0)+NVL(:P99_ADJUSTMENT,0);',
'    END IF;  ',
'END;'))
,p_attribute_02=>'P99_MONTHLY_FEE,P99_OPENING_BALANCE,P99_ADJUSTMENT,P99_STUDENT_IDS,P99_FEE_MONTH'
,p_attribute_03=>'P99_PAYABLE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
