'  V_CNT NUMBER;',
'',
'BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM STUDENT_FEES F ',
'   WHERE F.STATUS = ''A''',
'     AND F.STUDENT_ID = :P102_STUDENT_ID',
'     AND F.SITE_ID = :APP_SITE_ID',
'     ;   ',
'     IF V_CNT = 0 THEN',
'        RETURN TRUE;',
'      ELSE',
'         RETURN FALSE;',
'     END IF;',
'END;'))
